describe('cypress/e2e/renesas.com/categories-cards/categories-cards.spec.js', () => {
  
  describe('Categories Cards Block', { tags: ['categories-cards-block'] }, () => {
  
    it('(WW2-15361) Selected featured categories on product category node and is displayed in category section.', { tags: ['categories-cards-block', 'WW2-15361', 'admin', 'mlit', 'destructive'] }, () => {
      const timestamp = Date.now()
      const language = cy.config('language')
      const productCategoryUrl = 'node/add/product_category'
      const nodeTitle = `Test WW2-15361 - Product Category - ${language} - ${timestamp}`
  
      const featuredCategoryTitles = {
        en: ['Computing', 'Industrial'],
        zh: ['计算', '工业'],
        ja: ['コンピューティング', '産業用機器'],
      }
  
      cy.intercept({ method: 'POST', pathname: `**/${productCategoryUrl}**` }).as('ajaxSubmit')
  
      // Log in as admin and access the 'product category' node form
      cy.login(Cypress.env('account').admin)
      cy.visit(productCategoryUrl)
      cy.waitAdminToolbar()
  
      // Select page language
      cy.get('#edit-langcode-0-value').select((language === 'zh' ? 'zh-hans' : language))
  
      // Fill in required 'title' and 'long title' fields
      cy.get('#edit-title-0-value').type(nodeTitle)
      cy.wait('@ajaxSubmit').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-long-title-0-value').type(nodeTitle)
  
      // Fill in required description field
      cy.get('#edit-body-0-format--2').select('restricted_html', { force: true })
      cy.get('#edit-body-0-value').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('#edit-body-0-value').type(nodeTitle, { force: true })
  
      // Add a custom URL alias so non-English languages can be saved.
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-15361/${timestamp}`, { force: true })
  
      // Select 2 featured categories and save the node.
      cy.get('#field-featured-category-values input.form-element--type-text:first').type(featuredCategoryTitles.en[0], { force: true })
      cy.get('#edit-field-featured-category-add-more').click({ force: true })
      cy.wait('@ajaxSubmit').its('response.statusCode').should('eq', 200)
      cy.get('table[id^="field-featured-category-values"] input.form-element--type-text:last').type(featuredCategoryTitles.en[1], { force: true })
      cy.get('#edit-submit').click({ force: true })
  
      // Expect the selected featured categories to be displayed on the node page in order.
      cy.get('#block-renesas-blocks-product-category-categories .rcard2:first .rcard2__title').should('have.text', featuredCategoryTitles[language][0])
      cy.get('#block-renesas-blocks-product-category-categories .rcard2:last .rcard2__title').should('have.text', featuredCategoryTitles[language][1])
    })
  
  })
  
})

