          cy.get('@mailBody').should('contain', `Application: ${projectInformation.application}`)
          cy.get('@mailBody').should('contain', `Product: ${projectInformation.endProduct}`)
          cy.get('@mailBody').should('contain', `Estimated annual volume: ${projectInformation.estimate}`)
          cy.get('@mailBody').should('contain', `Integrated Circuits?: ${projectInformation.productionChina}`)
          cy.get('@mailBody').should('contain', `semiconductors in China?: ${projectInformation.productionChina}`)
          // user information
          cy.get('@mailBody').contains(`Email: ${Cypress.env('account').authenticated.username}`, { matchCase: false })
          cy.get('@mailBody').contains(`First name: ${Cypress.env('account').authenticated.firstName}`, { matchCase: false })
          cy.get('@mailBody').contains(`Last name: ${Cypress.env('account').authenticated.lastName}`, { matchCase: false })
          cy.get('@mailBody').contains(`Company: ${Cypress.env('account').authenticated.company}`, { matchCase: false })
          cy.get('@mailBody').contains(`Phone: ${Cypress.env('account').authenticated.phone}`, { matchCase: false })
          cy.get('@mailBody').should('contain', `Company website: ${contactInformation.website}`)
          // shipping information
          cy.get('@mailBody').should('contain', `Shipping email: ${Cypress.env('account').authenticated.username}`)
          cy.get('@mailBody').should('contain', `Shipping first name: ${Cypress.env('account').authenticated.firstName}`)
          cy.get('@mailBody').should('contain', `Shipping last name: ${Cypress.env('account').authenticated.lastName}`)
          cy.get('@mailBody').should('contain', `Shipping company: ${Cypress.env('account').authenticated.company}`)
          cy.get('@mailBody').should('contain', `Shipping phone: ${Cypress.env('account').authenticated.phone}`)
