      cy.get('#edit-field-product-id-0-value').type(`Test Cypress WW2-7799 - ${timestamp}`, { force: true })
      cy.get('#edit-title-0-value').type(`Test Cypress WW2-7799 - ${timestamp}`, { force: true })
