describe('cypress/e2e/renesas.com/duns/duns_destructive_2.spec.js', () => {
  
  describe('DUNS - DESTRUCTIVE', { tags: 'duns' }, () => {
  
    it('(WW2-15841) User receives email when a document is published from a subscribed page', { tags: ['duns', 'generic-product-documentation-tab', 'WW2-15841', 'authenticated', 'destructive'] }, () => {
  
      const genericProductPath = 'products/microcontrollers-microprocessors/rz-mpus/rza1lu-rtos-mpu-3mb-chip-ram?doc_order=date&doc_sort=asc&tab=documentation'
  
      // Log in as admin
      // Enable DUNS notify settings
      cy.login(Cypress.env('account').admin)
      cy.enableDunsNotifySettings()
  
      // Access product page
      // Save the title and nodeID of the oldest document in the documentation table
      // Save title of the product
      cy.visit(genericProductPath)
      cy.get('.documentation-search__hits--recommended .asr--b-document .asr__heading a').first().invoke('data', 'nid')
        .as('firstDocNid', { type: 'static' })
      cy.get('.documentation-search__hits--recommended .asr--b-document .asr__heading a .ais-Snippet').first().invoke('text')
        .as('documentTitle', { type: 'static' })
      cy.get('h1.title').invoke('text')
        .as('productName', { type: 'static' })
  
      // Edit the oldest doc in the documentation table
      // Switch its status to Draft
      cy.get('@firstDocNid').then((firstDocNid) => {
        cy.visit(`/node/${firstDocNid}/edit`)
      })
      cy.get('#edit-moderation-state-0-state').select('archived')
      cy.get('#edit-submit').click()
  
      // Clear and reset DUNS settings for the nonlisted user
      cy.clearResetDunsSettings(Cypress.env('account').nonlisted.userId)
  
      // Clear the DUNS email queue for the nonlisted user
      cy.clearDunsEmailQueue(Cypress.env('account').nonlisted.userId)
  
      // Log out
      // Log in as 'nonlisted' user
      cy.logout()
      cy.login(Cypress.env('account').nonlisted)
  
      // Subscribe the user to the page
      cy.visit(genericProductPath)
      // Wait all behaviors are attached and blocks ready.
      cy.wait(8000)
      cy.get('a.subscribe-link.subscribe-to-document-updates-link').click({ force: true })
      cy.wait(5000)
      cy.visit(`user/${Cypress.env('account').nonlisted.userId}/document-notifications`)
      // Verify the user is subscribed to the page.
      cy.get('table.responsive-enabled tbody tr.odd td a').should('contain', 'RZ/A1LU')
  
      // Log out
      // Log in as admin
      cy.logout()
      cy.login(Cypress.env('account').admin)
  
      // Edit the oldest doc in the product page and switch it to Published.
      cy.visit(genericProductPath)
      cy.get('@firstDocNid').then((firstDocNid) => {
        cy.visit(`/node/${firstDocNid}/edit`)
      })
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      // Access Send DUNS emails page
      cy.visit('admin/config/renesas/qa/duns')
      cy.get('#edit-user-id').clear()
      cy.get('#edit-user-id').type(Cypress.env('account').nonlisted.userId)
      cy.get('#edit-preview').click({ force: true })
      cy.get('.messages__content').should('exist')
        .and('contain', `Preview table updated to show records for User ID ${Cypress.env('account').nonlisted.userId}.`)
  
      // Verify latest DUNS queue entries for nonlisted user
      cy.get('@firstDocNid').then((firstDocNid) => {
        cy.get('#edit-preview-table tbody tr td').should('contain', Cypress.env('account').nonlisted.userId)
          .and('contain', firstDocNid)
      })
  
      // Clear DUNS queue and send email to mail safety
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages__content').should('exist')
        .and('contain', `DUNS notification processed for User ID ${Cypress.env('account').nonlisted.userId}.`)
  
      // Get the latest email the nonlisted user received in mail safety
      // Expect it to include the product name
      cy.getLastUserEmailInMailSafety(Cypress.env('account').nonlisted.role).then(($emailContent) => {
        cy.get('@productName').then((productName) => {
          expect($emailContent).to.include(productName)
        })
        cy.get('@documentTitle').then((documentTitle) => {
          expect($emailContent).to.include(documentTitle)
        })
      })
    })
  })
  
})

