      const automaticSubscription = [
        'No - do not automatically subscribe me to documents I download',
        'Yes - automatically subscribe me to any document I download',
        'Yes - automatically subscribe me to all documents related to the page',
        'Ask me every time']
  
      // Log in as authenticated user
