      cy.get('#notify-subscribe-form > .section-title').should('have.text', 'Automatic subscription management')
      cy.get('#edit-automatic-subscription-on-download option').each(($el, index) => {
        const option = $el.text().trim()
        expect(option).to.have.eq(automaticSubscription[index])
      })
  
