      cy.get('@titleField').type(`${blogPostTitle} - New Revision`)
  
      // Save node
      cy.get('@submitNodeButton').click()
  
      // Click on 'Revisions' tab
      cy.get('.tabs__tab a[href$="/revisions"]').click({ force: true })
  
      // Click on 'Revert' button
