      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
  
      // Add a custom URL alias
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(pageURL, { force: true })
  
      // Set the moderation to published.
      // Save node
      cy.get('#edit-moderation-state-0-state').as('moderationField').select('published')
      cy.get('#edit-submit').as('submitNodeButton').click()
  
      // Access the translations tab
      cy.get('.tabs__tab a[href$="/translations"]').click({ force: true })
  
      // Add a translation
      // Update node title
      cy.get('#edit-languages .add > .r').first().click({ force: true })
      cy.get('@titleField').clear({ force: true })
      cy.get('@titleField').type(`${blogPostTitle} - Translated`)
  
      // Set moderation to Draft
      // Save the node
      cy.get('@moderationField').select('draft')
      cy.get('@submitNodeButton').click()
  
      // Expect to see 'Draft' status
      cy.get('#edit-current').should('contain', 'Draft')
  
      // Click on the view tab
      // Expect to not see translated title
      cy.get('.tabs__tab:first-child a').click({ force: true })
      cy.get('#block-kachow-pagetitle h1').should('not.contain', 'Translated')
