      const timestamp = Date.now()
      const language = cy.config('language')
      const parentCategoryNodeId = '1498256'
      const productId = `WW2-15619 - ${timestamp}`
      const genericProductTitle = `Test WW2-15619 - Generic Product - ${language} - ${timestamp}`
