      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
  
      // Select a Parent Category
      cy.get('@parentCategory').then((parentCategory) => {
        cy.get('#edit-field-parent-category-sub-0-target-id').type(parentCategory)
      })
      cy.get('#edit-field-parent-category-sub-0-target-id').should('not.have.class', '.ui-autocomplete-loading')
