      // Select 'published' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      // Click on the Orderable Parts tab and link an orderable part number
      cy.get('.tabs__tab a[href$="/orderable-parts"]').as('orderablePartNode').should('be.visible')
      cy.get('@orderablePartNode').click({ force: true })
