      cy.get('#edit-part-number').type(orderablePartNumber)
      cy.get('select[name="generic_product_orderable_parts_filter"]').select('All', { force: true })
      cy.get('#edit-submit-generic-product-orderable-parts').click()
      cy.get('.renesas-relationships-ajax').click()
