        cy.get('input[name=field_block_diagram_application_block_diagram_add_more]').click({ force: true })
        cy.wait('@route').its('response.statusCode').should('eq', 200)
  
        // Type the Block Diagram title with a suffix
        cy.get('.field--name-field-block-diagram-title input').eq(index - 1).type(`Block Diagram Test Title ${index}`, { force: true })
  
        // Add a Functional Blocks
