describe('cypress/e2e/renesas.com/main-menu/main-menu.spec.js', () => {
  
  describe('Main Menu / Mega Menu', { tags: ['main-menu'] }, () => {
  
    it('(WW2-10634-01) User can open main menu item and access the menu subgroup', { tags: ['main-menu', 'WW2-10634', 'WW2-10634-01', 'mlit', 'anonymous'] }, () => {
      // Open home page
      // Click to open the Product mega menu
      cy.visit('')
      cy.get('.megamenu .sub-nav a').should('have.class', 'r')
      cy.get('#block-kachow-mainmenu button.megamenu__link').first().click({ force: true })
  
      // Expect product menu to open and be visible
      cy.get('.nav-menu .nav-item').first().should('have.class', 'open')
      cy.get('.product-submenu').should('exist').and('be.visible').and('have.attr', 'style').and('not.be.empty')
  
      // Click on the second Product subgroup
      // Expect the item to expand
      cy.get('.products-submenu .sub-nav-group a').eq(1).as('productSubmenuOption').click({ force: true })
      cy.get('@productSubmenuOption').should('have.attr', 'aria-expanded', 'true')
    })
  
    it('(WW2-10634-02) User should see featured items blue background', { tags: ['main-menu', 'WW2-10634', 'WW2-10634-02', 'mlit', 'anonymous'] }, () => {
      // Open home page
      // Click on the first menu item that has Featured Items
      cy.visit('')
      cy.get('.megamenu .sub-nav a').should('have.class', 'r')
      cy.get('#block-kachow-mainmenu li.nav-item--with-featured-section').first().within(() => {
        cy.get('button').first().click({ force: true })
  
        // Expect the corresponding submenu to be visible
        cy.get('> .is-level-2').first().should('exist').and('be.visible').and('have.attr', 'style').and('not.be.empty')
  
        // Expect the featured section to have a pseudo element with a background
        cy.get('li.nav-item--featured-section').first().then(($element) => {
          // Get Window reference from element
          const window = $element[0].ownerDocument.defaultView
          // Use getComputedStyle to read the pseudo selector (:before)
          const beforeSelector = window.getComputedStyle($element[0], ':before')
          // Read the computed value of the `background-color` CSS property
          const bgColor = beforeSelector.getPropertyValue('background-color')
          // Expect the background color to be blue
          expect(bgColor).to.equal('rgb(235, 242, 251)')
        })
      })
    })
  
    it('(WW2-10634-03) User should see all main tabs of the mega menu expanded when click on them', { tags: ['main-menu', 'WW2-10634', 'WW2-10634-03', 'mlit', 'anonymous'] }, () => {
      // Open home page
      // Click all level 1 menu buttons
      // Expect the corresponding submenu to be visible
      cy.visit('')
      cy.get('.megamenu .sub-nav a').should('have.class', 'r')
      cy.get('#block-kachow-mainmenu button.megamenu__link').each(($button) => {
        const $submenu = $button.parent().find('> .is-level-2')
        cy.wrap($button).click()
        cy.wrap($submenu).should('exist').and('be.visible')
      })
    })
  
    it('(WW2-10634-04) User can close mega menu by clicking on the X button', { tags: ['main-menu', 'WW2-10634', 'WW2-10634-04', 'mlit', 'anonymous'] }, () => {
  
      // Create alias to wait for menu to load
      cy.intercept('**/ajax/menu-endpoint').as('loadMainMenu')
  
      // Open home page
      // Click on the first menu item
      cy.visit('')
      cy.get('.megamenu .sub-nav a').should('have.class', 'r')
      cy.get('#block-kachow-mainmenu button.megamenu__link').first().as('firstMenuItem')
      cy.get('@firstMenuItem').should('have.attr', 'aria-expanded', 'false')
      cy.get('@firstMenuItem').should('be.visible').click({ force: true })
      cy.wait('@loadMainMenu').its('response.statusCode').should('eq', 200)
      cy.wait(1000) // Small wait is needed here to let the mega menu opening animation to finish.
  
      // Expect menu to expand
      // Expect menu options to be visible
      cy.get('@firstMenuItem').should('have.attr', 'aria-expanded', 'true')
      cy.get('@firstMenuItem')
        .parent('li')
        .find('.is-level-2').as('menuOptions')
        .should('be.visible')
        .and('have.attr', 'style')
        .and('not.include', 'overflow: hidden;')
      cy.wait(2000)
  
      // Click on the close button
      cy.get('@menuOptions')
        .find('.ricon-close')
        .first().as('closeButton')
        .should('be.visible')
        .click({ force: true })
  
      /**
       * Expect:
       *  - menu to collapse
       *  - menu options to not be visible
       *  - close button to not be visible
       */
      cy.get('@firstMenuItem').should('have.attr', 'aria-expanded', 'false')
      cy.get('@menuOptions').should('not.be.visible').and('have.attr', 'style').and('be.empty')
      cy.get('@closeButton').should('not.be.visible')
    })
  
    it('(WW2-10634-05) User can close mega menu by clicking on the search button', { tags: ['main-menu', 'WW2-10634', 'WW2-10634-05', 'mlit', 'anonymous'] }, () => {
      // Open home page
      // Click on the first menu item
      cy.visit('')
      cy.get('.megamenu .sub-nav a').should('have.class', 'r')
      cy.get('#block-kachow-mainmenu button.megamenu__link').first().as('firstMenuItem').should('be.visible').click({ force: true })
  
      // Expect menu to expand
      // Expect menu options to be visible
      cy.get('@firstMenuItem').should('have.attr', 'aria-expanded', 'true')
      cy.get('@firstMenuItem').parent('li').find('.is-level-2').should('be.visible').and('have.attr', 'style').and('not.include', 'overflow: hidden;')
  
      // Click on the search button
      // Expect menu to collapse
      cy.get('#block-kachow-algoliapresearchblock .search-link > a').click({ force: true })
      cy.get('@firstMenuItem').should('have.attr', 'aria-expanded', 'false')
    })
  })
  
})

describe('cypress/e2e/renesas.com/news-additional-resources/news-additional-resources.spec.js', () => {
  
  describe('News & Additional Resources', { tags: ['news-additional-resources'] }, () => {
  
    const testData1 = {
      en: {
        newsAdditionalResourceHeaderTitle: 'News & Additional Resources',
        relatedNewsAdditionalResource: 'Renesas Tool News'
      },
      ja: {
        newsAdditionalResourceHeaderTitle: 'ニュース&各種リソース',
        relatedNewsAdditionalResource: 'Renesas ツールニュース'
      },
      zh: {
        newsAdditionalResourceHeaderTitle: '新闻及更多资源',
        relatedNewsAdditionalResource: 'Renesas Tool News'
      },
    }
  
    it('(WW2-8802) User can add \'Related News & Additional Resources\' component to a blog post node', { tags: ['news-additional-resources', 'WW2-8802', 'mlit', 'admin', 'destructive'] }, () => {
  
      const { newsAdditionalResourceHeaderTitle } = testData1[cy.config('language')]
      const { relatedNewsAdditionalResource } = testData1[cy.config('language')]
  
      cy.login(Cypress.env('account').admin)
  
      // Visit blog post test page
      cy.visit('blogs/test-page-blog-post-ct-do-not-publish-or-edit-please')
  
      // Verify if RELATED NEWS & ADDITIONAL RESOURCES block already exists on front end
      // If exists goto edit tab and remove it
      cy.get('body').then(($body) => {
        if ($body.find('#block-renesas-blocks-additional-resources').length > 0) {
          cy.get(':nth-child(2) > .tabs__tab-link').click({ force: true })
          cy.waitAdminToolbar()
          cy.get('#edit-field-related-resources-0-target-id').clear()
          cy.get('#edit-moderation-state-0-state').select('draft')
          cy.get('#edit-submit').click()
          cy.get('html body').should('not.contain', newsAdditionalResourceHeaderTitle)
        }
      })
  
      // Goto edit tab
      cy.get(':nth-child(2) > .tabs__tab-link').click({ force: true })
      cy.waitAdminToolbar()
  
      // Add related news & additional resources
      cy.get('#edit-field-related-resources-0-target-id').clear()
      cy.get('#edit-field-related-resources-0-target-id').type(relatedNewsAdditionalResource)
  
      // Select 'draft' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('draft')
      cy.get('#edit-submit').click()
  
      /**
         * Expect:
         *  - to see 'page has been updated' message
         *  - to see 'News & Additional Resources' table title
         *  - to see RELATED NEWS & ADDITIONAL RESOURCES under 'News & Additional Resources' table
         */
      cy.get('.messages').should('contain', 'Blog Post').should('contain', 'has been updated')
      cy.get('.block-renesas-blocks-additional-resources h2').should('contain', newsAdditionalResourceHeaderTitle)
      cy.get('.block-renesas-blocks-additional-resources tbody .r').should('contain', relatedNewsAdditionalResource)
    })
  })
  
})

describe('cypress/e2e/renesas.com/newsletter-subscription/newsletter-subscription.spec.js', () => {
  
  describe('Newsletter Subscription', { tags: ['newsletter-subscription'] }, () => {
  
    const testData1 = {
      en: {
        newsletterURL: 'https://info.renesas.com/newsletter-signup-en',
        errorMessage: 'There are errors, please check your responses and try again',
        successMessage: 'Submission confirmed!'
      },
      ja: {
        newsletterURL: 'https://info.renesas.com/newsletter-signup-ja',
        errorMessage: '必須チェック項目を確認してください。',
        successMessage: 'ご登録が完了しました'
      },
      zh: {
        newsletterURL: 'https://www2.info.renesas.cn/newsletter-signup-cn',
        errorMessage: '请按照正确格式填写， 重新提交',
        successMessage: '已确认提交！'
      }
    }
  
    it('(WW2-10005-01) User can submit newsletter form', { tags: ['newsletter-subscription', 'WW2-10005-01', 'mlit', 'anonymous'] }, () => {
      const { newsletterURL } = testData1[cy.config('language')]
      const { successMessage } = testData1[cy.config('language')]
  
      // Access the newsletter form is different depending on the environment (tugboat or prod)
      cy.onProdEnv().then(($onProd) => {
  
        /**
          * On tugboat, we need to use cy.origin to access the newsletter form
          * as its url domain is different from the base URL
          */
        if (!$onProd) {
          cy.origin(newsletterURL, () => {
            cy.visit('')
          })
  
          /**
           * On prod, the domains are the same and we don not need cy.origin
           */
        } else {
          cy.visit('')
          cy.get('.newsletter a.button').invoke('removeAttr', 'target').click({ force: true })
        }
      })
  
      // Fill in all required fields
      cy.get('#C_FirstName').clear()
      cy.get('#C_FirstName').type(Cypress.env('account').authenticated.firstName)
      cy.get('#C_LastName').clear()
      cy.get('#C_LastName').type(Cypress.env('account').authenticated.lastName)
      cy.get('#C_Company').clear()
      cy.get('#C_Company').type('Renesas')
      cy.get('#C_Country').select('PT')
      cy.get('#C_EmailAddress').clear()
      cy.get('#C_EmailAddress').type(Cypress.env('account').authenticated.username)
      cy.get('#C_Job_Role1').select('Other')
      cy.get('#RegionalTerms').check()
  
      // Click on submit
      cy.get('[type="submit"]').click()
  
      // Expect to see success message
      cy.url().should('contain', 'submissionStatus=success')
      cy.get('#submission-confirmation').should('contain', successMessage)
    })
  
    it('(WW2-10005-02) User cannot submit newsletter form without filling in required fields', { tags: ['newsletter-subscription', 'WW2-10005-02', 'mlit', 'anonymous'] }, () => {
      const { newsletterURL } = testData1[cy.config('language')]
      const { errorMessage } = testData1[cy.config('language')]
  
      // Access the newsletter form is different depending on the environment (tugboat or prod)
      cy.onProdEnv().then(($onProd) => {
  
        /**
          * On tugboat, we need to use cy.origin to access the newsletter form
          * as its url domain is different from the base URL
          */
        if (!$onProd) {
          cy.origin(newsletterURL, () => {
            cy.visit('')
          })
  
          /**
           * On prod, the domains are the same and we don not need cy.origin
           */
        } else {
          cy.visit('')
          cy.get('.newsletter a.button').invoke('removeAttr', 'target').click({ force: true })
        }
      })
  
      // Expect required fields to NOT HAVE red border
      cy.get('#C_FirstName').as('firstName').should('not.have.class', 'error')
      cy.get('#C_LastName').as('lastName').should('not.have.class', 'error')
      cy.get('#C_Company').as('company').should('not.have.class', 'error')
      cy.get('#C_Country').as('country').should('not.have.class', 'error')
      cy.get('#C_EmailAddress').as('email').should('not.have.class', 'error')
      cy.get('#C_Job_Role1').as('jobRole').should('not.have.class', 'error')
      cy.get('#regional-terms').as('termsConditions').should('not.have.class', 'error')
  
      // Click on submit
      cy.get('[type="submit"]').click()
  
      // Expect browser alert to have correct text
      cy.on('window:alert', (txt) => {
        expect(txt).to.contains(errorMessage)
      })
  
      // Expect required fields to HAVE red border
      cy.get('@firstName').should('have.class', 'error')
      cy.get('@lastName').should('have.class', 'error')
      cy.get('@company').should('have.class', 'error')
      cy.get('@country').should('have.class', 'error')
      cy.get('@email').should('have.class', 'error')
      cy.get('@jobRole').should('have.class', 'error')
      cy.get('@termsConditions').should('have.class', 'error')
    })
  })
  
})

describe('cypress/e2e/renesas.com/node-form/application-category-node-form.spec.js', () => {
  
  describe('Application Category Node Form', { tags: ['cms', 'application-category-node-form'] }, () => {
  
    it('(WW2-8574-01) User can publish new application category node', { tags: ['cms', 'application-category-node-form', 'WW2-8574', 'WW2-8574-01', 'mlit', 'admin', 'destructive'] }, () => {
  
      const timestamp = Date.now()
      const language = cy.config('language')
      const applicationCategoryTitle = `Test WW2-8574-01 - Application Category - ${language} - ${timestamp}`
      const successMessage = `Application Category ${applicationCategoryTitle} has been created`
      const newApplicationCategoryUrl = 'node/add/application_category'
  
      cy.intercept({ method: 'POST', pathname: `**/${newApplicationCategoryUrl}**` }).as('searchDuplicateTitle')
  
      // Log in as admin and access the 'application category' node form
      cy.login(Cypress.env('account').admin)
      cy.visit(newApplicationCategoryUrl)
      cy.waitAdminToolbar()
  
      // Select page language
      cy.get('#edit-langcode-0-value').select((language === 'zh' ? 'zh-hans' : language))
  
      // Fill in 'title' and 'long title' fields
      cy.get('#edit-title-0-value').type(applicationCategoryTitle)
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-long-title-0-value').type(applicationCategoryTitle)
  
      // Change description field to 'restrict html' and fill it in
      cy.get('#edit-body-0-format--2').select('restricted_html', { force: true })
      cy.get('#edit-body-0-value').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('#edit-body-0-value').type(applicationCategoryTitle)
  
      // Add a custom URL alias
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-8574-01/${timestamp}`, { force: true })
  
      // Select 'published' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      /**
       * Expect:
       *  - to not see 'draft' moderation status
       *  - title to be correct
       *  - to see 'page has been created' message
       */
      cy.get('#block-kachow-mainpagecontent article').should('not.contain', 'Draft').and('not.contain', 'draft').and('not.have.class', 'is-unpublished')
      cy.get('h1').should('contain', applicationCategoryTitle)
      cy.get('.messages').should('contain', successMessage)
    })
  
    it('(WW2-9839-01) User can add translation to application category node', { only: ['an:jp:ja', 'an:cn:zh'], tags: ['cms', 'WW2-9839-01', 'application-category-node-form', 'mlit', 'admin', 'destructive'] }, () => {
  
      const timestamp = Date.now()
      const language = cy.config('language')
      const applicationCategoryTitle = `Test WW2-9839-01 - Application Category - ${language} - ${timestamp}`
      const newApplicationCategoryUrl = 'node/add/application_category'
      const successMessage = `Application Category ${applicationCategoryTitle} has been updated`
      const hreflang = language === 'zh' ? 'zh-hans' : language
  
      cy.intercept({ method: 'POST', pathname: `**/${newApplicationCategoryUrl}**` }).as('searchDuplicateTitle')
  
      // Log in as admin and access the 'page' node form
      cy.login(Cypress.env('account').admin)
      cy.visit(newApplicationCategoryUrl)
      cy.waitAdminToolbar()
  
      // Select EN in language field
      cy.get('[data-drupal-selector="edit-langcode-0-value"]').select('en')
  
      // Fill in 'title' and 'long title' fields
      cy.get('#edit-title-0-value').type(applicationCategoryTitle)
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-long-title-0-value').type(applicationCategoryTitle)
  
      // Change description field to 'restrict html' and fill it in
      cy.get('#edit-body-0-format--2').select('restricted_html', { force: true })
      cy.get('#edit-body-0-value').type(applicationCategoryTitle)
  
      // Select 'published' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      // Add a translation
      cy.get('li.tabs__tab a[href$="/translations"]').click({ force: true })
      cy.get(`a[hreflang="${hreflang}"][href*="/add/"]`)
        .click({ force: true })
  
      // Fill in page title field
      cy.get('#edit-title-0-value').as('titleField').clear()
      cy.get('@titleField').type(applicationCategoryTitle)
  
      cy.get('#edit-field-long-title-0-value').as('longTitleField').clear()
      cy.get('@longTitleField').type(applicationCategoryTitle)
  
      // Change description field to 'restrict html' and fill it in
      cy.get('#edit-body-0-format--2').select('restricted_html', { force: true })
      cy.get('#edit-body-0-value').type(applicationCategoryTitle)
  
      // Select 'published' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      /**
       * Expect:
       *  - translated title to be correct
       *  - to see 'page has been created' message
       */
      cy.get('h1').should('contain', applicationCategoryTitle)
      cy.get('.messages').should('contain', successMessage)
  
    })
  
    it('(WW2-9948-03) Authenticated user get correct dynamic cache when accessing a application category page', { tags: ['cms', 'application-category-node-form', 'WW2-9948', 'WW2-9948-03', 'mlit', 'authenticated'] }, () => {
      const pageURL = 'applications/industrial'
  
      // Logs in as auth user and intercept the page url
      cy.login(Cypress.env('account').authenticated)
      cy.intercept(`**/${pageURL}`).as('applicationCategoryPage')
  
      // Visit the page and wait for the response code to be 200
      cy.visit(pageURL)
      cy.get('@applicationCategoryPage').its('response.statusCode').should('eq', 200)
  
      // Expect response headers dynamic cache to equals HIT or MISS
      cy.get('@applicationCategoryPage').its('response.headers').then(($responseHeaders) => {
        expect($responseHeaders['x-drupal-dynamic-cache']).to.be.oneOf(['HIT', 'MISS'])
      })
    })
  
    it('(WW2-11537-01) Verify the same categories are shown on all languages', { tags: ['application-category-node-form', 'application-categories-categories', 'WW2-11537', 'WW2-11537-01', 'anonymous'] }, () => {
  
      const categoryListEN = []
      const categoryListZH = []
      const categoryListJA = []
  
      // Access application search page
      cy.visit('applications/industrial')
  
      // Get EN Categories Nids
      // eslint-disable-next-line cypress/unsafe-to-chain-command
      cy.get('#block-renesas-blocks-application-subcategories .rcard a.rcard__title').each(($row) => {
        const nodeID = $row.attr('data-nid')
        categoryListEN.push(nodeID)
      }).then(() => {
  
        // Go to JA page
        cy.wait(1000)
        cy.get('#block-kachow-accountmenu .language').click({ force: true })
        cy.get('#block-kachow-accountmenu .language__menu a.lang-ja').click({ force: true })
  
        // Get JA Categories Nids
        // eslint-disable-next-line cypress/unsafe-to-chain-command
        cy.get('#block-renesas-blocks-application-subcategories .rcard a.rcard__title').each(($row) => {
          const nodeID = $row.attr('data-nid')
          categoryListJA.push(nodeID)
        }).then(() => {
  
          // Expect EN and JA category lists to have the same count
          expect(categoryListEN.length).to.equal(categoryListJA.length)
          // Expect JA node to have same categories as EN.
          categoryListEN.forEach((item) => {
            expect(categoryListJA.includes(item))
          })
        })
  
        // Go to ZH page
        cy.wait(1000)
        cy.get('#block-kachow-accountmenu .language').click({ force: true })
        cy.get('#block-kachow-accountmenu .language__menu a.lang-zh-hans').click({ force: true })
  
        // Get ZH Categories Nids
        // eslint-disable-next-line cypress/unsafe-to-chain-command
        cy.get('#block-renesas-blocks-application-subcategories .rcard a.rcard__title').each(($row) => {
          const nodeID = $row.attr('data-nid')
          categoryListZH.push(nodeID)
        }).then(() => {
  
          // Expect EN and ZA category lists to have the same count
          expect(categoryListEN.length).to.equal(categoryListZH.length)
          // Expect ZH node to have same categories as EN.
          categoryListEN.forEach((item) => {
            expect(categoryListZH.includes(item))
          })
        })
      })
    })
  })
  
})

