      const testId = '10606-02'
      const timestamp = Date.now()
      // Setting up the url alias requires English language.
      const language = 'en'
      const nodeTitle = `Test WW2-${testId} - Board / Kit - ${language} - ${timestamp}`
      const createPath = 'node/add/evaluation_board'
      const autoAlias = `/${language}/design-resources/boards-kits/ww2-${testId}`
      const customAlias = `/test-cypress-${testId}/${timestamp}`
      const productId = `WW2-${testId} - ${timestamp}`
      const { parentCategory } = testData1[language]
  
      cy.intercept({ method: 'POST', pathname: `**/${createPath}**` }).as('searchDuplicateTitle')
  
      // Log in as admin and access the node form
      cy.login(Cypress.env('account').admin)
      cy.visit(createPath)
      cy.waitAdminToolbar()
  
      // Fill in 'title' field
