describe('cypress/e2e/renesas.com/orderable-product/orderable-product-page.spec.js', () => {
  
  describe('Orderable Product Page', { tags: ['orderable-product-content-type'] }, () => {
  
    it('(WW2-15395-01) User can access Orderable page', { tags: ['orderable-product-content-type', 'WW2-15395', 'WW2-15395-01', 'mlit', 'anonymous'] }, () => {
  
      const language = cy.config('language')
      const testData1 = {
        en: {
          subtitle: '32-bit Microcontrollers with 120MHz Medium Size Memory Integration and Ethernet',
          activeText: 'Active',
          description: 'The Renesas RA6M2 group of microcontrollers (MCUs) uses the high-performance Arm® Cortex®-M4 core and offers Ethernet MAC with individual DMA, to ensure high data throughput. The RA6M2 is built on a highly efficient 40nm process and is supported by an open and flexible ecosystem concept—the Flexible Software Package (FSP), built on FreeRTOS—and is expandable to use other RTOSes and middleware. The RA6M2 is suitable for IoT applications requiring Ethernet, security, large embedded RAM, and low active power consumption.',
        },
        ja: {
          subtitle: '120MHz動作、中容量メモリ、Ethernet内蔵の 32 ビットマイクロコントローラ',
          activeText: 'アクティブ',
          description: 'RA6M2 MCUグループは、高性能Arm® Cortex®-M4コアを搭載しており、チャネル毎にDMAを備えたEthernet MACによって優れたデータ スループットを実現します。高効率な40nmプロセスで製造されており、オープンで柔軟なエコシステム(FSP、FreeRTOS)をサポートしています。もちろん他のRTOSやミドルウェアも使用できるように拡張可能です。RA6M2 は、Ethernet、セキュリティ、大容量RAMを搭載した組込みシステム、低消費電力を必要とするIoTアプリケーションに適しています。',
        },
        zh: {
          subtitle: '带有 120 MHz 中型以太网存储器集成的 32 位微控制器',
          activeText: '有效',
          description: '瑞萨电子 RA6M2 微控制器 (MCU) 群组使用高性能 Arm® Cortex®-M4 内核，提供具有单独 DMA 的以太网 MAC，可确保高的数据吞吐量。RA6M2 采用高效的 40nm 工艺，由开放且灵活的生态系统概念提供支持，即基于 FreeRTOS 的灵活配置软件包 (FSP)，能够扩展以使用其他 RTOSes 和中间件。RA6M2 适用于需要以太网、安全性、大型嵌入式 RAM 和较低功耗的物联网应用。',
        }
      }
  
      const rohsLinksByLang = {
        en: [
          { label: 'English', expectedPathParts: ['-en', '.pdf'] },
          { label: 'Japanese', expectedPathParts: ['-ja', '.pdf'] }
        ],
        ja: [
          { label: '英語', expectedPathParts: ['-en', '.pdf'] },
          { label: '日本語', expectedPathParts: ['-ja', '.pdf'] }
        ],
        zh: [
          { label: '英语', expectedPathParts: ['-en', '.pdf'] },
          { label: '日文', expectedPathParts: ['-ja', '.pdf'] }
        ]
      }
  
      const OrderablePartUrl = 'products/ra6m2/part-details/r7fa6m2ad2clk-ac0'
      const partNumber = 'R7FA6M2AD2CLK#AC0'
      const parentNodeUrl = 'products/ra6m2'
  
      // Visit orderable page.
      cy.visit(OrderablePartUrl)
  
      // Heading block contains all necessary info.
      cy.get('.title.part__id').should('contain', partNumber)
      cy.get('.part__label').should('contain', testData1[language].activeText)
      cy.get('.part-heading__subtitle').should('contain', testData1[language].subtitle)
      cy.get('.document-link.document-link-loaded').first().click({ force: true })
      cy.get('#rmm-dun-modal').should('be.visible').and('have.class', 'is-open')
      cy.get('.rmm__close').click({ force: true })
      // Link to parent node - redirects to the parent node
      cy.get('.view-more-link').first().click({ force: true })
      cy.url().should('include', parentNodeUrl)
      cy.go('back')
      // Images (came from parent node) - image enlarged when clicking on it
      cy.get('.field--name-field-media-image a').first().click({ force: true })
      cy.get('#rmm2-loader').should('be.visible').and('have.class', 'is-open')
      cy.get('[data-micromodal-close="rmm2-loader"]').first().click({ force: true })
  
      // Package block is shown
      cy.get('#block-renesas-blocks-package').should('be.visible')
  
      // Environmental block
      rohsLinksByLang[language].forEach(({ label, expectedPathParts }) => {
        // Locate the link by visible text (e.g., English, Japanese)
        cy.contains('td a', label)
          .should('have.attr', 'href')
          .then(() => {
  
            // Optionally click the link in same tab for further assertions
            cy.contains('td a', label)
              .invoke('removeAttr', 'target')
              .click({ force: true })
  
            // Confirm the correct PDF is opened
            cy.url().should('include', expectedPathParts[0]).and('include', expectedPathParts[1])
  
            cy.go('back')
          })
      })
      // Do not display RoHS links if there are no files,
      cy.visit('products/9dbu0441/part-details/9dbu0441aklft')
      cy.get('a.rlink-icon').should('not.exist')
      cy.go('back')
  
      // Product attributes block.
      // Verify View All links expands all options
      cy.get('#view-all-attributes').should('be.visible').scrollIntoView()
      cy.get('#view-all-attributes').trigger('mouseover')
      cy.get('#view-all-attributes').click({ force: true })
  
      // Description block.
      // Contains link to the parent node
      cy.get('#block-renesas-blocks-description .view-more-link').should('be.visible')
      // Description is the same as for the parent node
      cy.get('#block-renesas-blocks-description .description').contains(testData1[language].description)
  
    })
  
    it('(WW2-15395-02) User can see breadcrumb extended with orderable part number on part detail page', { tags: ['orderable-product-content-type', 'WW2-15395', 'WW2-15395-02', 'mlit', 'anonymous'] }, () => {
  
      const OrderablePartUrl = 'products/ra6m2/part-details/r7fa6m2ad2clk-ac0'
  
      // Visit orderable page.
      cy.visit(OrderablePartUrl)
  
      cy.get('.view-more-link').first().scrollIntoView()
      cy.get('.view-more-link').first().invoke('attr', 'href')
        .then((href) => {
          // Extract the last segment of the URL path
          const lastSegment = href.split('/').pop() // ex: "ra6m2-32-bit-microcontrollers-..."
          const productCode = lastSegment.split('-')[0].toUpperCase() // "RA6M2"
  
          cy.get('#block-kachow-breadcrumbs')
            .scrollIntoView()
  
          cy.get('#block-kachow-breadcrumbs ol li')
            .eq(-2)
            .invoke('text')
            .then((breadcrumbText) => {
              const cleanedBreadcrumb = breadcrumbText.trim().toUpperCase()
              expect(cleanedBreadcrumb).to.include(productCode)
  
              cy.log(`✅ Product code "${productCode}" found in breadcrumb: "${cleanedBreadcrumb}"`)
            })
        })
    })
  
    it('(WW2-15395-03) User can view pricing and \'Add to cart\' block on orderable product page', { tags: ['orderable-product-content-type', 'WW2-15395', 'WW2-15395-03', 'mlit', 'authenticated'] }, () => {
  
      const OrderablePartUrl = 'products/icm7211am/part-details/icm7211amiplz'
      // Log in as authenticated
      // Access the orderable product page
      cy.login(Cypress.env('account').authenticated)
  
      // Visit orderable page.
      cy.visit(OrderablePartUrl)
      // Enter Quantity and verify that Price per quantity is updated based on the price table below
      // And Subtotal is properly updated based on the price table
      const quantityToTest = 10
      // Scroll and enter the quantity
      cy.get('input.buy-cart--quantity-input').as('quantityField').should('be.visible')
      cy.get('@quantityField').clear({ force: true })
      cy.get('@quantityField').type(quantityToTest.toString(), { force: true })
  
      // Get the expected unit price from the price table dynamically
      let matchedPrice = null
      let expectedSubtotal = null
      cy.get('.table-wrapper table tbody tr').then((rows) => {
  
        rows.each((index, row) => {
          const quantityCell = Cypress.$(row).find('td').eq(0).text().trim()
          const priceCell = Cypress.$(row).find('td.unit-price').text().trim()
  
          if (parseInt(quantityCell, 10) === quantityToTest) {
            matchedPrice = parseFloat(priceCell.replace('$', ''))
          }
        })
  
        expect(matchedPrice, 'Price found for entered quantity').to.not.be.null
  
        expectedSubtotal = (quantityToTest * matchedPrice).toFixed(3)
  
        // Verify that the visible unit price matches the one in the table
        cy.get('.price-indicator')
          .invoke('text')
          .then((visiblePrice) => {
            const parsedPrice = parseFloat(visiblePrice.replace('$', ''))
            expect(parsedPrice).to.eq(matchedPrice)
          })
  
        // Verify the subtotal
        cy.get('.sub-total-value')
          .invoke('val')
          .then((subtotal) => {
            expect(parseFloat(subtotal.replace('$', ''))).to.eq(Number(expectedSubtotal))
          })
      })
  
      // Click to Add to Cart and verify “Cart Update” popup
      // appears and contains correct quantity and price.
      cy.get('.buy-now').click({ force: true })
      cy.get('#rmm2-loader').should('be.visible').and('have.class', 'is-open')
      cy.get('#rmm2-loader').within(() => {
        cy.get('.additional-info li').eq(1).invoke('text').then((qtyText) => {
          const qty = parseInt(qtyText.replace(/\D/g, ''), 10)
          expect(qty).to.eq(quantityToTest)
        })
  
        cy.get('.additional-info li').eq(2).invoke('text').then((priceText) => {
          const unitPrice = parseFloat(priceText.replace(/[^0-9.]/g, ''))
          expect(unitPrice).to.eq(matchedPrice)
        })
  
        cy.get('.additional-info li').eq(3).invoke('text').then((subtotalText) => {
          const subtotal = parseFloat(subtotalText.replace(/[^0-9.]/g, ''))
          expect(subtotal).to.eq(parseFloat(expectedSubtotal))
        })
      })
    })
  
    it('(WW2-15395-04) User can see “Buy from Distributor” section displayed below the direct purchase', { tags: ['orderable-product-content-type', 'WW2-15395', 'WW2-15395-04', 'mlit', 'authenticated'] }, () => {
  
      const OrderablePartUrl = 'products/ra6m2/part-details/r7fa6m2ad2clk-ac0'
      // Log in as authenticated
      // Access the orderable product page
      cy.login(Cypress.env('account').authenticated)
  
      // Visit orderable page.
      cy.visit(OrderablePartUrl)
  
      // Expect 'Buy from Distributor' to be placed after 'Buy direct'
      cy.get('section#block-renesas-blocks-pricing-and-add-to-cart').then(($buyDirect) => {
        cy.get('section#block-renesas-blocks-buy-from-distributors').then(($distributor) => {
          const buyDirectIndex = $buyDirect.index()
          const distributorIndex = $distributor.index()
  
          expect(distributorIndex).to.be.greaterThan(buyDirectIndex)
        })
      })
  
      // Verify Find a Distributor in Your Area link below
      // “Buy from distributors is shown and redirects to the Saleas locations page
      // Verify that the "Find a Distributor in Your Area" link is visible
      cy.get('.find-distributor')
        .should('be.visible')
        .and('have.attr', 'href')
        .then((href) => {
          // Confirm the href points to the expected URL
          expect(href).to.include('/sample-buy/locations')
  
          // Optionally: click the link and verify redirection
          cy.get('.find-distributor')
            .invoke('removeAttr', 'target') // prevent opening in a new tab
            .click({ force: true })
  
          cy.url().should('include', '/sample-buy/locations')
        })
  
    })
  
    it('(WW2-16676-01) User can add a new Orderable part in admin', { tags: ['orderable-product-content-type', 'cms', 'WW2-16676-01', 'mlit', 'destructive'] }, () => {
  
      const timestamp = Date.now()
      const partAdmin = 'admin/content/parts'
      const partName = `New-part-test-${timestamp}`
      const partAttribute = 'field__display_1k_unit_price'
      const partAttributeValue = '5.5'
      const pagePartCreatedURl = `orderable-product/${partName}`
  
      // Log in as admin.
      // Access the orderable product page.
      cy.login(Cypress.env('account').admin)
      cy.visit(partAdmin)
  
      // Click to Add Orderable Part.
      cy.get('[data-drupal-link-system-path="part/add"]').click({ force: true })
      // Enter title.
      cy.get('#edit-part-number-0-value').type(partName)
      // Enter attribute.
      cy.get('#edit-field-attr-0-controls-add-attr').type(partAttribute)
      cy.get('#edit-field-attr-0-controls-add-attr-button').click({ force: true })
      // Enter attribute value.
      cy.get('[data-drupal-selector="edit-field-attr-0-attrs-field-display-1k-unit-price-0"]').should('be.visible').type(partAttributeValue)
      // Save page.
      cy.get('#edit-submit').click({ force: true })
  
      // Visit orderable page.
      cy.visit(pagePartCreatedURl)
      // Verify that displays correct attribute Price (USD)  $priceand value.
      cy.get('[data-once="renesasBlocksPartAttributes"]').as('productAttributes')
        .should('contain', 'Price (USD)')
        .and('contain', partAttributeValue)
  
      // Go to any Generic Product, Orderable Parts tab.
      cy.visit('node/434396/generic-product/orderable-parts')
      // Get and store the productID value.
      cy.get('.breadcrumb__link').first().invoke('text').then((text) => {
        cy.wrap(text.trim()).as('productID')
      })
      // Search for the new part.
      cy.get('#edit-part-number').type(partName)
      cy.get('#edit-generic-product-orderable-parts-filter').select('All')
      cy.get('#edit-submit-generic-product-orderable-parts').click({ force: true })
      // Link part
      cy.get('[data-action-type="orderable_product"]').click({ force: true })
      cy.get('.ajax-progress .throbber').should('have.attr', 'style').and('match', /display: none;|display:none;/)
      // Verify it has a new URL: instead of /orderable-product/{{title}}
      // it redirects to /products/<generic productID>/part-details/<title>.
      cy.get('@productID').then((productID) => {
        const path = `/products/${productID}/part-details/${partName}`
        cy.visit(path)
        // Verify that the element is visible and its content includes the partName on the new page.
        cy.get('.title.part__id')
          .should('be.visible')
          .invoke('text')
          .should('include', partName)
  
        cy.get('@productAttributes')
          .should('contain', 'Price (USD)')
          .and('contain', partAttributeValue)
      })
    })
  })
  
})

