      cy.get('#edit-body-0-value').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('#edit-body-0-value').type(applicationCategoryTitle)
      // Add a custom URL alias
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-16843-02/${timestamp}`, { force: true })
      // Select 'published' status
      // Click on Save
      cy.get('#edit-moderation-state-0-state').select('published')
      cy.get('#edit-submit').click()
  
      // Create alias to wait for 'parametric table' options to load
      cy.intercept('**ajax_form=1&_wrapper_format=drupal_ajax**').as('loadParametricTableSection')
  
      // ADD CUSTOM PARAMETRIC TABLE WITH SEARCH OPTIONS AND GENERIC PRODUCTS.
      // Edit the node.
