      // Save as Renesas_com_published (staged version)
      cy.get('#edit-moderation-state-0-state').select('renesas_com_published', { force: true })
      cy.get('#edit-submit').click({ force: true })
  
      // STEP 3: VERIFY BOTH VERSIONS
  
      // View node with staging Disabled (published version)
      cy.get(`li.tabs__tab a[title='${viewLabel[language]}']`).click({ force: true })
  
      // Verify published content still shows (not staged content)
      cy.get('.block-page-title-block h1').should('contain', pageTitle)
      cy.get('.block-page-title-block h1').should('not.contain', pageTitleStaged)
      cy.get('.wysiwyg').should('contain', wysiwygTextarea)
      cy.get('.wysiwyg').should('not.contain', wysiwygTextareaStaged)
  
      // Verify Cards published content (not staged content)
      cy.get('.paragraph--type--cards h2').should('contain', cardsGITitle)
