      cy.waitAdminToolbar()
      cy.get('#block-renesas-products-table-block').within(() => {
        cy.get('.tab-columns').should('be.visible').click({ force: true })
        cy.get(`[col-id="${productOptionPublished}"]`).should('exist')
        cy.get(`[col-id="${productOptionStaged}"]`).should('not.exist')
      })
  
      // Enable staging mode
