      cy.intercept('**/parametric-search/fields/autocomplete?**').as('parametricSearchAutocomplete')
      cy.intercept('**/entity_reference_autocomplete/**').as('genericProductAutocomplete')
  
      // Log in as admin.
      cy.login(Cypress.env('account').admin)
  
      // STEP 1: CREATE THE PUBLISHED VERSION
  
      cy.visit(newPageUrl)
