      // Fill in long title
      cy.get('#edit-field-long-title-0-value').type(pageTitle)
  
      // Add Custom Parametric Table
      cy.get('#edit-group-ets-parametric-table summary').click({ force: true })
      cy.get('#edit-field-ets-parametric-table-add-more-add-more-button-ets-parametric-table').click({ force: true })
      cy.wait('@loadParametricTableSection').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress.ajax-progress--throbber').should('not.exist')
  
      // Select type 'Generic Product'
      cy.get('[data-drupal-selector="edit-field-ets-parametric-table-0-subform-field-display-type"] input[value="generic"]').check()
  
      // Add Parametric Search option
      cy.get('[data-drupal-selector="edit-field-ets-parametric-table-0-subform-field-parametric-search-0-value"]').as('parametricSearch').should('exist').and('be.visible')
      cy.get('@parametricSearch').type(productOption, { force: true })
      cy.wait('@parametricSearchAutocomplete').its('response.statusCode').should('eq', 200)
  
      // Add Generic Product
      cy.get('[data-drupal-selector="edit-field-ets-parametric-table-0-subform-field-ets-generic-products-0-target-id"]').as('genericProduct').should('exist').and('be.visible')
      cy.get('@genericProduct').type(genericProduct, { force: true })
      cy.wait('@genericProductAutocomplete').its('response.statusCode').should('eq', 200)
      cy.get('ul.ui-autocomplete:visible > li.ui-menu-item:first > a').click({ force: true })
  
      // Add custom URL alias
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-16507/${timestamp}`, { force: true })
  
      // Save as 'published'.
      cy.get('#edit-moderation-state-0-state').select('published', { force: true })
      cy.get('#edit-submit').click()
  
      // Edit node and save with additional option and product.
      // Tests can be flaky when adding these second options on initial creation.
      cy.get('.tabs__tab a[href$="/edit"]').click({ force: true })
      cy.get('#edit-group-ets-parametric-table summary').click({ force: true })
      cy.get('[data-drupal-selector="edit-field-ets-parametric-table-0-subform-field-parametric-search-1-value"]').as('newParametricSearch').clear()
      cy.get('@newParametricSearch').type(productOptionPublished, { force: true })
      cy.wait('@parametricSearchAutocomplete').its('response.statusCode').should('eq', 200)
      cy.get('[data-drupal-selector="edit-field-ets-parametric-table-0-subform-field-ets-generic-products-1-target-id"]').as('newGenericProduct').type(genericProductPublished, { force: true })
      cy.wait('@genericProductAutocomplete').its('response.statusCode').should('eq', 200)
      cy.get('ul.ui-autocomplete:visible > li.ui-menu-item:first > a').click({ force: true })
      cy.get('#edit-submit').click()
  
      // STEP 2: CREATE THE STAGED VERSION
  
