describe('cypress/e2e/renesas.com/preview-on-prod/software-category.spec.js', () => {
  
  describe('Preview on Prod', { tags: ['preview-on-prod'] }, () => {
  
    it('(WW2-16123-01) User can preview Software Category - Software List component in staging mode', { tags: ['preview-on-prod', 'WW2-16123-01', 'mlit', 'admin', 'destructive'] }, () => {
      const timestamp = Date.now()
      const language = cy.config('language')
      const softwareCategoryTitle = `Test WW2-16123-01 - Software Category - ${language} - ${timestamp}`
      const publishText = 'Original published text'
      const stagingText = 'Test WW2-16123-01 Staging text'
      const newSoftwareCategoryUrl = 'node/add/software_category'
  
      // Alias intercept for duplicate title validation
      cy.intercept({ method: 'POST', pathname: `**/${newSoftwareCategoryUrl}**` }).as('searchDuplicateTitle')
  
      // Log in as admin
      cy.login(Cypress.env('account').admin)
  
      // Create new Software category node
      cy.waitAdminToolbar()
      cy.visit(newSoftwareCategoryUrl)
  
      // Fill in title and type fields
      cy.get('#edit-title-0-value').type(softwareCategoryTitle, { force: true })
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-software-type').select(3, { force: true })
  
      // Select page language
      // Add a custom URL alias
      cy.get('#edit-langcode-0-value').select((language === 'zh' ? 'zh-hans' : language))
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-16123-01/${timestamp}`, { force: true })
  
      // Open software list section
      cy.get('#edit-group-software-list summary').as('softwareListGroup').scrollIntoView()
      cy.get('@softwareListGroup').click({ force: true })
  
      // Alias common form elements
      cy.get('select[id^="edit-field-software-list-details-0-format--2"]').as('textFormatSelect')
      cy.get('textarea[id^="edit-field-software-list-details-0-value"]').first().as('softwareTextarea')
      cy.get('#edit-moderation-state-0-state').as('moderationSelect')
      cy.get('#edit-submit').as('submitButton')
  
      // Edit software list details field
      cy.get('@textFormatSelect').select('restricted_html', { force: true })
      cy.get('@softwareTextarea').should('have.attr', 'style', '')
      cy.get('@softwareTextarea').type(publishText, { force: true, delay: 0 })
  
      // Publish node
      cy.get('@moderationSelect').select('published')
      cy.get('@submitButton').click({ force: true })
  
      // Edit node again
      cy.get('.tabs__tab a[href$="/edit"]').click({ force: true })
      cy.waitAdminToolbar()
  
      // Update software list details to staging text
      cy.get('@softwareListGroup').scrollIntoView()
      cy.get('@softwareTextarea').clear({ force: true })
      cy.get('@softwareTextarea').type(stagingText, { force: true, delay: 0 })
  
      // Save as RSTAGE publish
      cy.get('@moderationSelect').select('renesas_com_published')
      cy.get('@submitButton').click({ force: true })
  
      // Access published version (click on view)
      cy.get('.tabs__tab:first-child a').click({ force: true })
  
      // Expect publish version to:
      //  - contain publish text
      //  - not contain staging text
      cy.get('#block-renesas-blocks-software-category p').as('softwareBlock')
        .should('be.visible')
        .and('contain', publishText)
        .and('not.contain', stagingText)
  
      // Enable staging mode
      cy.enableStagingMode()
  
      // Expect staging version to:
      //  - not contain publish text
      //  - contain staging text
      cy.get('@softwareBlock')
        .should('be.visible')
        .and('not.contain', publishText)
        .and('contain', stagingText)
    })
  
    it('(WW2-16123-02) User can preview Software Category - Support component in staging mode', { tags: ['preview-on-prod', 'WW2-16123-02', 'mlit', 'admin', 'destructive'] }, () => {
      const timestamp = Date.now()
      const language = cy.config('language')
      const softwareCategoryTitle = `Test WW2-16123-01 - Software Category - ${language} - ${timestamp}`
      const publishText = 'Original published support text'
      const stagingText = 'Test WW2-16123-02 Staging text'
      const newSoftwareCategoryUrl = 'node/add/software_category'
  
      // Create alias to wait for elements to load
      cy.intercept({ method: 'POST', pathname: `**/${newSoftwareCategoryUrl}**` }).as('searchDuplicateTitle')
      cy.intercept('**ajax_form=1&_wrapper_format=drupal_ajax**').as('loadSupportFields')
  
      // Log in as admin
      cy.login(Cypress.env('account').admin)
  
      // Create new Software category node
      cy.visit(newSoftwareCategoryUrl)
      cy.waitAdminToolbar()
  
      // Fill in title and type fields
      cy.get('#edit-title-0-value').type(softwareCategoryTitle, { force: true })
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-software-type').select(3, { force: true })
  
      // Select page language
      // Add a custom URL alias
      cy.get('#edit-langcode-0-value').select((language === 'zh' ? 'zh-hans' : language))
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-16123-01/${timestamp}`, { force: true })
  
      // Add new Support
      cy.get('#field-support-support-add-more').as('supportSection').scrollIntoView()
      cy.get('@supportSection').click({ force: true })
      cy.wait('@loadSupportFields').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress.ajax-progress--throbber').should('not.exist')
      cy.get('#field-support-add-more-wrapper .ajax-new-content').should('have.attr', 'style', '')
      cy.wait(1500)
  
      // Change details textfield to 'restricted html'
      // Fill in support optional details field
      cy.get('select[data-drupal-selector="edit-field-support-0-subform-field-body-0-format"]').select('restricted_html', { force: true })
      cy.get('textarea[data-drupal-selector="edit-field-support-0-subform-field-body-0-value"]').as('supportOptionalDetails').should('have.attr', 'style', '')
      cy.get('@supportOptionalDetails').type(publishText, { force: true })
  
      // Publish node
      cy.get('#edit-moderation-state-0-state').as('moderationField').select('published')
      cy.get('#edit-submit').as('submitButton').click({ force: true })
  
      // Edit node again
      cy.get('.tabs__tab a[href$="/edit"]').click({ force: true })
      cy.get('#field-support-values').scrollIntoView()
  
      // Click to Edit support section
      cy.get('#field-support-values [data-drupal-selector^="field-support-0-edit"]').click({ force: true })
      cy.wait('@loadSupportFields').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress.ajax-progress--throbber').should('not.exist')
      // cy.wait(1500)
  
      // Update support optional details to staging text
      cy.get('@supportOptionalDetails').clear({ force: true })
      cy.get('@supportOptionalDetails').type(stagingText, { force: true, delay: 0 })
  
      // Save as RSTAGE published
      cy.get('@moderationField').select('renesas_com_published')
      cy.get('@submitButton').click()
  
      // Access published version (click on view)
      cy.get('.tabs__tab:first-child a').click({ force: true })
  
      // Expect publish version to:
      //  - contain publish text
      //  - not contain staging text
      cy.get('#block-renesas-support-optional-details-block p').as('softwareBlock')
        .should('be.visible')
        .and('contain', publishText)
        .and('not.contain', stagingText)
  
      // Enable staging mode
      cy.enableStagingMode()
  
      // Expect staging version to:
      //  - not contain publish text
      //  - contain staging text
      cy.get('@softwareBlock')
        .should('be.visible')
        .and('not.contain', publishText)
        .and('contain', stagingText)
    })
  
    it('(WW2-16123-03) User can preview Software Category - Videos & Training component in staging mode', { tags: ['preview-on-prod', 'WW2-16123-03', 'admin', 'destructive'] }, () => {
      const timestamp = Date.now()
      const softwareCategoryTitle = `Test WW2-16123-03 - Software Category - ${timestamp}`
      const publishRelatedVideo = 'Boost Vision AI'
      const stagingRelatedVideo = 'RZ/V2M Pose Estimation'
      const newSoftwareCategoryUrl = 'node/add/software_category'
  
      // Alias intercept for duplicate title validation
      cy.intercept({ method: 'POST', pathname: `**/${newSoftwareCategoryUrl}**` }).as('searchDuplicateTitle')
  
      // Log in as admin
      cy.login(Cypress.env('account').admin)
  
      // Create new Software category node
      cy.waitAdminToolbar()
      cy.visit(newSoftwareCategoryUrl)
  
      // Fill in title and type fields
      cy.get('#edit-title-0-value').type(softwareCategoryTitle, { force: true })
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('#edit-field-software-type').select(3, { force: true })
  
      // Open Videos & Training section
      cy.get('#edit-group-videos-training summary').as('videosTrainingSection').scrollIntoView()
      cy.get('@videosTrainingSection').click({ force: true })
  
      // Add related video
      cy.get('#edit-field-video-page-ref-0-target-id').as('relatedVideoField').type(publishRelatedVideo, { force: true })
      cy.get('ul.ui-autocomplete:visible > li.ui-menu-item:first > a').click({ force: true })
  
      // Save node
      cy.get('#edit-moderation-state-0-state').as('moderationField').select('published')
      cy.get('#edit-submit').as('submitButton').click({ force: true })
  
      // Edit node again
      cy.get('.tabs__tab a[href$="/edit"]').click({ force: true })
      cy.waitAdminToolbar()
      cy.get('@videosTrainingSection').scrollIntoView()
      cy.get('@videosTrainingSection').click({ force: true })
  
      // Update related video
      cy.get('@relatedVideoField').clear({ force: true })
      cy.get('@relatedVideoField').type(stagingRelatedVideo, { force: true })
      cy.get('ul.ui-autocomplete:visible > li.ui-menu-item:first > a').click({ force: true })
  
      // Save as RSTAGE published
      cy.get('@moderationField').select('renesas_com_published', { force: true })
      cy.get('@submitButton').click({ force: true })
  
      // Access published version (click on view)
      cy.get('.tabs__tab:first-child a').click({ force: true })
  
      // Expect publish version to:
      //  - contain publish related video
      //  - not contain staging related video
      cy.get('.block-renesas-blocks-videos-training iframe').as('videosTrainingBlock').scrollIntoView()
      cy.get('@videosTrainingBlock').should('exist').and('be.visible')
      cy.get('@videosTrainingBlock')
        .its('0.contentDocument.body')
        .then(cy.wrap)
        .find('.ee-components-style-videoTitle')
        .should('contain', publishRelatedVideo)
        .and('not.contain', stagingRelatedVideo)
  
      // Enable staging mode
      cy.enableStagingMode()
  
      // Expect staging version to:
      //  - not contain publish related video
      //  - contain staging related video
      cy.get('@videosTrainingBlock').scrollIntoView()
      cy.get('@videosTrainingBlock').should('exist').and('be.visible')
      cy.get('@videosTrainingBlock')
        .its('0.contentDocument.body')
        .then(cy.wrap)
        .find('.ee-components-style-videoTitle')
        .should('not.contain', publishRelatedVideo)
        .and('contain', stagingRelatedVideo)
    })
  })
  
})

