describe('cypress/e2e/renesas.com/product-options-table/product-options-modal_2.spec.js', () => {
  
  describe('Product Options Modal', { tags: ['product-tables-ag-grid'] }, () => {
  
    it('(WW2-15980-01) User can get samples using the product options modal', { tags: ['product-tables-ag-grid', 'WW2-15980', 'WW2-15980-01', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      const confirmationMessage = {
        en: 'has been added to your sample requests.',
        ja: 'がサンプルリクエストに追加されました。',
        zh: '已添加到您的样本请求中。',
      }
      const warningMessage = {
        en: 'is already in your sample request.',
        ja: 'はすでにサンプルリクエストに含まれています。',
        zh: '已包含在您的样本请求中。',
      }
      // Access product page
      cy.visit('products/microcontrollers-microprocessors/ra-cortex-m-mcus/ra2a2-48mhz-arm-cortex-m23-ultra-low-power-general-purpose-microcontroller-rich-peripherals?tab=product-options')
      cy.waitForParametricTable()
  
      // Add one sample to the cart
      cy.addSamplesToCart(0)
  
      // User can click to Request sample and see
      // “Product has been added to your sample requests” confirmation message.
      cy.get('[col-id="sampleable"] a').first().click({ force: true })
      cy.get('#rmm2-loader').should('be.visible')
      cy.get('#rmm2-loader .notification').contains(confirmationMessage[language])
  
      // Clicking to “View Requests” redirects to the Sample request page where can see added sample.
      cy.get('a.view-requests').click({ force: true })
      cy.url().should('contain', '/sample-request?')
  
      // User is not able to add same sample twice.
      // User sees “This part is already in your sample request.”
      // message after trying to request the same part and can close popup by clicking “Ok”
      cy.go('back')
      cy.get('[col-id="sampleable"] a').first().click({ force: true })
      cy.get('#rmm2-loader').should('be.visible')
      cy.get('#rmm2-loader .notification').contains(warningMessage[language])
    })
  
    it('(WW2-15980-02) User is not able to add more then 5 samples to the cart', { tags: ['product-tables-ag-grid', 'WW2-15980', 'WW2-15980-02', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
  
      const warningMessage = {
        en: 'No more than 5 parts can be added to the sample request.',
        ja: 'サンプルリクエストには、5型名以上は追加できません。',
        zh: '样品请求不能添加超过 5 个器件。',
      }
      // Access product page
      cy.visit('products/microcontrollers-microprocessors/ra-cortex-m-mcus/ra6e2-entry-line-200mhz-arm-cortex-m33-general-purpose-microcontroller?tab=product-options')
  
      cy.get('#block-renesas-products-table-block').should('be.visible')
  
      cy.intercept('**/ajax/sample-request/?**').as('sample')
  
      // Add one sample to the cart
      cy.addSamplesToCart(5)
  
      // Add the sixth product (index 5)
      cy.get('[col-id="sampleable"] a').eq(5).click({ force: true })
      cy.waitPartNumberModal()
      cy.wait('@sample').its('response.statusCode').should('eq', 200)
      // User tries to request 5 different parts and sees
      // “No more than 5 parts can be added to the sample request.” message.
      cy.get('#rmm2-loader .notification').contains(warningMessage[language])
    })
  
  })
  
})

describe('cypress/e2e/renesas.com/product-options-table/product-options-special-columns.spec.js', () => {
  
  describe('Product Option Table', { tags: ['product-tables-ag-grid'] }, () => {
  
    it('(WW2-15982-01) ColumnLongevity (PLP) - Slider', { tags: ['product-tables-ag-grid', 'WW2-15982-01', 'mlit', 'anonymous'] }, () => {
      cy.visit('/products/microcontrollers-microprocessors/rl78-low-power-8-16-bit-mcus/rl78g12-compact-low-power-microcontrollers-general-purpose-applications-ideal-sub-mcus?sort-by=field-plp_desc#parametric_options')
  
      // Verify Dual slider filter is shown and user can filter between — and 2037
      cy.get('.ag-header-cell[aria-colindex="4"] .ag-floating-filter-button-button').click()
  
      // Verify that the filter dialog appears
      cy.get('.ag-filter').should('be.visible')
      cy.get('.agr-cf-minmax__slider').should('be.visible')
  
      // Verify that only for this parameter user is not able
      // to enter values manually, only use slider
      cy.get('.agr-cf-minmax__min').should('be.disabled')
      cy.get('.agr-cf-minmax__max').should('be.disabled')
  
      // Verify slider has only two positions (min=0, max=1)
      cy.get('.range-slider__thumb[data-lower]')
        .should('have.attr', 'aria-valuemin', '0')
        .should('have.attr', 'aria-valuemax', '4')
  
      // Test case 1: Default position should show both "—" and "2037"
      cy.get('.ag-cell[aria-colindex="4"]').should('contain', '2036')
  
      // Move slider to position 1 - should filter out "—", only show "2037"
      cy.get('.range-slider__thumb[data-lower]')
        .as('slider')
        .focus()
      cy.get('@slider').type('{rightarrow}', { force: true }) // Move right once to position 1
  
      cy.get('.range-slider__thumb[data-lower]')
        .should('have.attr', 'aria-valuenow', '1') // Verify position is 1
  
      // Verify "—" is filtered out but "2037" is visible
      cy.get('.ag-cell[aria-colindex="4"]').each(($cell) => {
        const cellText = $cell.text().trim()
        expect(cellText).not.to.equal('—')
      })
      cy.get('.ag-cell[aria-colindex="4"]').should('contain', '2036')
  
      // Reset the filter to default position
      cy.get('.agr-cf-minmax__reset').click({ force: true })
  
      // Verify both values are shown again
      cy.get('.ag-cell[aria-colindex="4"]').should('contain', '2036')
    })
  
    it('(WW2-15982-02) ColumnLongevity (PLP) - Checkbox', { tags: ['product-tables-ag-grid', 'WW2-15982-02', 'mlit', 'anonymous'] }, () => {
      cy.visit('products/microcontrollers-microprocessors/ra-cortex-m-mcus/ra0e1-32mhz-arm-cortex-m23-entry-level-ultra-low-power-general-purpose-microcontroller?sort-by=field-plp_desc#parametric_options')
  
      // Verify If Dual slider filter has <= 2 options and shows checkboxes
      cy.get('.ag-header-cell[aria-colindex="4"] .ag-floating-filter-button-button').click({ force: true })
  
      let selectedCheckboxText = '' // variable to store the label text
  
      cy.get('.ag-virtual-list-container')
        .find('.ag-filter-virtual-list-item')
        .then(($items) => {
          expect($items.length).to.be.lte(3)
  
          if ($items.length >= 2) {
            // Work within the second item
            cy.wrap($items)
              .eq(1)
              .within(() => {
                // Get the label text
                cy.get('[data-ref="eLabel"]')
                  .invoke('text')
                  .then((text) => {
                    selectedCheckboxText = text.trim()
                    cy.log('Selected checkbox label text:', selectedCheckboxText)
                  })
  
                // Click the checkbox
                cy.get('input[type="checkbox"]').check({ force: true })
              })
          }
        })
  
      cy.wait(1000) // Optional: wait for rows to load after filtering
  
      // Step 3: Verify all rows under col-id="field__plp" contain the checkbox text
      cy.get('[col-id="field__plp"] .ag-cell-value').each(($cell) => {
        const cellText = $cell.text().trim()
        expect(cellText).to.eq(selectedCheckboxText)
      })
  
    })
  
    it('(WW2-15982-03) Column Package', { tags: ['product-tables-ag-grid', 'WW2-15982-03', 'mlit', 'anonymous'] }, () => {
      cy.visit('products/ra0e1#parametric_options')
  
      // Expect filter menus to be available
      cy.get('#block-renesas-products-table-block').within(() => {
  
        cy.get('.ag-header-cell[aria-colindex="8"] .ag-floating-filter-button-button').click({ force: true })
        cy.get('.ag-header-cell[aria-colindex="8"] ').first().click({ force: true })
  
      })
      // Verify package info modal is opened when click on the Package type link
      cy.get('.ag-cell[aria-colindex="8"] a')
        .first()
        .click({ force: true })
      cy.get('#rmm2-loader')
        .should('exist').and('have.class', 'is-open')
      // User can close the modal by clicking on the “x” icon
      cy.get('.rmm2__close').click({ force: true })
      // User can click on the “View More Package Info link
      // and it redirects to the corresponding Package page
      cy.get('.ag-cell[aria-colindex="8"] a')
        .first()
        .click({ force: true })
      cy.get('#rmm2-loader')
        .should('exist').and('have.class', 'is-open')
  
      cy.get('.rmm2__footer a.button')
        .should('exist')
        .invoke('attr', 'href')
        .then((expectedURL) => {
          cy.get('.rmm2__footer a.button').click({ force: true })
  
          cy.url().should('include', expectedURL)
        })
  
    })
  
    it('(WW2-15982-04) Column CAD model', { tags: ['product-tables-ag-grid', 'WW2-15982-04', 'mlit', 'anonymous'] }, () => {
  
      cy.visit('products/78k0-dx2#parametric_options')
  
      // Verify that the products table block is visible on the page.
      cy.get('#block-renesas-products-table-block').should('be.visible')
      // Select the tab with the class 'tab-columns'
      // Click on the Columns menu to filter all columns.
      cy.get('.tab-columns')
        .should('be.visible')
        .click({ force: true })
  
      // Click to "Select All" checkbox (all columns are unchecked and hidden in the table).
      cy.get('.ag-column-select-header-checkbox input[type="checkbox"]')
        .check({ force: true })
      // Navigate to the parent element
      // and make sure the checkboxes are checked so that the necessary columns appear.
      cy.get('.ag-column-select-header-checkbox input[type="checkbox"]')
        .should('be.checked')
        .parent()
        .should('have.class', 'ag-checked')
  
      // Verify CAD Modal is present and user can click on it and see modal
      cy.get('.ag-cell[aria-colindex="5"] a')
        .first()
        .click({ force: true })
      cy.get('#rmm2-loader')
        .should('exist').and('have.class', 'is-open')
      // User can close the modal by clicking on the “x” icon
      cy.get('.rmm2__close').click()
  
    })
  
    it('(WW2-15982-05) Column RoHS', { tags: ['product-tables-ag-grid', 'WW2-15982-05', 'mlit', 'anonymous'] }, () => {
  
      cy.visit('/products/space-harsh-environment/rad-hard-hermetic/rad-hard-power/rad-hard-load-switches/isl70062seh-radiation-hardened-10a-nmos-load-switch#parametric_options')
  
      // Verify RoHS links for EN and JA are shown
      // and open documents in the new tab with correct language
      const rohsLinks = [
        {
          text: 'RoHS: EN',
          expectedPath: ['-en', '.pdf']
        },
        {
          text: 'RoHS: JA',
          expectedPath: ['-ja', '.pdf']
        }
      ]
  
      // Iterate over each link and check its redirection
      rohsLinks.forEach((link) => {
        // Find the specific link by its text
        cy.get('.rohs-links a')
          .contains(link.text)
          .should('have.attr', 'href')
          .then(() => {
            // Since these are links that open in a new tab (target="_blank"),
            // we can either verify the href attribute directly
            // or remove the target to navigate in the same window
            cy.get('.rohs-links a')
              .contains(link.text)
              .invoke('removeAttr', 'target')
              .click({ force: true })
  
            // Verify that the URL contains the expected part
            cy.url().should('include', link.expectedPath[0]).and('include', link.expectedPath[1])
  
            cy.go('back')
          })
      })
    })
  })
  
})

