describe('cypress/e2e/renesas.com/product-options-table/product-options-table_4.spec.js', () => {
  
  describe('Product Option Table', { tags: ['product-tables-ag-grid'] }, () => {
  
    it('(WW2-15978-03) Product option table There should be 20 products shown before the pager component', { tags: ['product-tables-ag-grid', 'WW2-15978-03', 'mlit', 'anonymous'] }, () => {
  
      cy.visit('/products/microcontrollers-microprocessors/ra-cortex-m-mcus/ra0e1-32mhz-arm-cortex-m23-entry-level-ultra-low-power-general-purpose-microcontroller#parametric_options')
      cy.get('.part-number', { timeout: 10000 }).should('be.visible')
  
      cy.get('.part-number').then(($products) => {
        expect($products.length).to.equal(20)
      })
    })
  
    it('(WW2-15978-04) User can click on the next page and see more table results', { tags: ['product-tables-ag-grid', 'WW2-15978-04', 'mlit', 'anonymous'] }, () => {
  
      cy.visit('/products/microcontrollers-microprocessors/ra-cortex-m-mcus/ra0e1-32mhz-arm-cortex-m23-entry-level-ultra-low-power-general-purpose-microcontroller#parametric_options')
  
      // Get total number of products
      cy.get('.ag-data-counter strong').first().invoke('text').then((text) => {
        const totalProducts = parseInt(text.trim(), 10)
        cy.wrap(totalProducts).as('totalProducts')
      })
  
      // Ensure pagination controls are visible and in view
      cy.get('.renesas-ag-grid__pagination', { timeout: 10000 })
        .should('be.visible')
        .scrollIntoView()
  
      // Click on the next page button
      cy.get('.renesas-ag-grid__pagination-control--next')
        .as('nextPageButton')
        .should('be.visible')
        .scrollIntoView()
      cy.get('@nextPageButton').click({ force: true })
  
      // Verify the number of products on the second page
      cy.get('@totalProducts').then((totalProducts) => {
        cy.get('.part-number').then(($products) => {
          expect($products.length).to.be.lessThan(totalProducts)
        })
      })
  
      // Go back to the previous page
      cy.get('.renesas-ag-grid__pagination-control--prev')
        .as('previousPageButton')
        .should('be.visible')
        .scrollIntoView()
      cy.get('@previousPageButton').click({ force: true })
  
      // Verify that the previous page button is no longer visible
      cy.get('.renesas-ag-grid__pagination-control--prev')
        .should('not.be.visible')
    })
  
    it('(WW2-16497-01) User can click through the pagination in full-screen mode', { tags: ['product-tables-ag-grid', 'WW2-16497-01', 'mlit', 'anonymous'] }, () => {
      const fullScreenButton = 'a.icon-link--full-screen'
      const sectionSelector = '#block-renesas-products-table-block'
  
      // Go to product page
      cy.visit('products/rl78-g1a?tab=product-options')
      // Verify that the block does not have the 'is-full-screen' class
      cy.get(sectionSelector).should('not.have.class', 'is-full-screen')
      // Click on the "Full Screen" button
      cy.get(fullScreenButton).should('be.visible').click({ force: true })
      // Assert that section now has 'is-full-screen'
      cy.url().should('include', 'full-screen')
  
      // Scroll to the bottom of the page
      // cy.scrollTo('bottom')
  
      // Ensure pagination controls are visible
      cy.get('.renesas-ag-grid__pagination').scrollIntoView()
      cy.get('.renesas-ag-grid__pagination', { timeout: 5000 })
        .should('be.visible')
  
      /**
       * Extracts the pagination range from the AG Grid pagination label.
       * The label contains three <strong> elements representing:
       * - current range start (from)
       * - current range end (to)
       * - total number of items (total)
       *
       * Returns an object: { from, to, total }
       */
      const getPaginationCounts = () => {
        return cy.get('.renesas-ag-grid__pagination-label strong').then(($strongs) => {
          const nums = [...$strongs].map((el) => { return parseInt(el.textContent.trim(), 10) })
          const sorted = nums.slice().sort((a, b) => { return a - b })
          return {
            from: sorted[0],
            to: sorted[1],
            total: sorted[2]
          }
        })
      }
  
      // First page assertions
      getPaginationCounts().then((firstPage) => {
        expect(firstPage.from).to.equal(1)
  
        const firstPageCount = firstPage.to - firstPage.from + 1
        const expectedSecondPageCount = firstPage.total - firstPageCount
  
        cy.log(`First page: ${firstPage.from}–${firstPage.to} of ${firstPage.total}`)
        cy.log(`Expected second page count: ${expectedSecondPageCount}`)
  
        // Check at least 1 item is rendered (even if grid is virtualized)
        cy.get('.part-number').should('have.length.greaterThan', 0)
  
        // Navigate to second page
        cy.get('.renesas-ag-grid__pagination-control--next')
          .should('be.visible')
          .click({ force: true })
  
        // Second page assertions
        getPaginationCounts().then((secondPage) => {
          const secondPageCount = secondPage.to - secondPage.from + 1
  
          cy.log(`Second page: ${secondPage.from}–${secondPage.to} of ${secondPage.total}`)
          cy.log(`secondPageCount page: ${secondPageCount}`)
  
          // Again, verify at least 1 row rendered
          cy.get('.part-number').should('have.length.greaterThan', 0)
        })
  
        // Go back
        cy.get('.renesas-ag-grid__pagination-control--prev')
          .should('be.visible')
          .click({ force: true })
  
        // Assert that the "previous page" button is not visible
        cy.get('.renesas-ag-grid__pagination-control--prev')
          .should('not.be.visible')
      })
    })
  })
  
})

