describe('cypress/e2e/renesas.com/product-selection-table/product-selection-filters_7.spec.js', () => {
  
  describe('Product Selection Table Filters', { tags: ['product-tables-ag-grid'] }, () => {
  
    it('(WW2-15976-06) User can filter table results (checkbox)', { tags: ['product-tables-ag-grid', 'WW2-15976', 'WW2-15976-06', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      const filterText = {
        en: 'Active',
        ja: 'アクティブ',
        zh: '有效',
      }
      // Access the product page
      cy.visit('/products/microcontrollers-microprocessors/rl78-low-power-8-16-bit-mcus/product-selector')
  
      // Open the filters
      cy.get('#tab-filters').click({ force: true })
  
      // Find the second filter panel and perform actions within it
      cy.get('.ag-filter-toolpanel-group-wrapper')
        .eq(2)
        .within(() => {
          // Click on the ag-group-title-bar-icon
          cy.get('.ag-filter-toolpanel-group-title').first().click({ force: true })
          cy.wait(3000)
  
          // Check only the third checkbox
          cy.get('input[type="checkbox"]')
            .eq(2) // Selecting the third checkbox (index 2)
            .check({ force: true })
        })
  
      // Assert that the first cell value in each row matches the selected checkbox label
      cy.get('.ag-center-cols-viewport .ag-row').each(($row) => {
        cy.wrap($row)
          .find('div[col-id="part_status"] .ag-cell-value')
          .first()
          .invoke('text')
          .should('eq', filterText[language])
      })
    })
  
    it('(WW2-15976-07) User can sort columns in ascending order', { tags: ['product-tables-ag-grid', 'WW2-15976', 'WW2-15976-07', 'mlit', 'anonymous'] }, () => {
      // Access the product page
      cy.visit('/products/microcontrollers-microprocessors/rl78-low-power-8-16-bit-mcus/product-selector')
  
      // Class should not be present on page load
      cy.get('div[col-id="field__program_memory"]')
        .find('.ag-cell-label-container')
        .should('not.have.class', 'ag-header-cell-sorted-asc')
  
      // Click on the Program Memory column header
      cy.get('div.ag-header-cell[col-id="field__program_memory"]').click()
  
      cy.wait(2000)
  
      // Assert that the ascending sort class appears
      cy.get('div[col-id="field__program_memory"]')
        .find('.ag-cell-label-container')
        .should('have.class', 'ag-header-cell-sorted-asc')
  
      // Assert that the ascending sort icon is visible
      cy.get('div[col-id="field__program_memory"]')
        .find('.ag-sort-ascending-icon')
        .should('not.have.class', 'ag-hidden')
  
      // Assert that the URL contains the correct sort parameter
      cy.url().should('include', '?sort-by=field-program-memory_asc')
  
      // Verify the sorting order is correct by comparing adjacent cell values
      // First get all cells in the Program Memory column
      cy.get('div[col-id="field__program_memory"][role="gridcell"]').then(($cells) => {
        // Only proceed if we have at least two cells to compare
        if ($cells.length >= 2) {
          // Loop through cells and verify sorting
          for (let i = 0; i < $cells.length - 1; i += 1) {
            // Extract the numeric values from the current and next cells
            const currentValue = parseInt($cells.eq(i).find('.ag-cell-value').text().trim(), 10)
            const nextValue = parseInt($cells.eq(i + 1).find('.ag-cell-value').text().trim(), 10)
  
            // Check that current value is less than or equal to the next value
            expect(currentValue).to.be.at.most(nextValue)
          }
        }
      })
    })
  
    it('(WW2-15976-08) User can sort columns in descending order', { tags: ['product-tables-ag-grid', 'WW2-15976', 'WW2-15976-08', 'mlit', 'anonymous'] }, () => {
      // Access the product page
      cy.visit('products/microcontrollers-microprocessors/other-mcus-mpus/product-selector')
  
      // Class should not be present on page load.
      cy.get('div[col-id="field__program_memory"]')
        .find('.ag-cell-label-container')
        .should('not.have.class', 'ag-header-cell-sorted-desc')
  
      // Click on the Program Memory column header.
      cy.get('div.ag-header-cell[col-id="field__bit_size"]').click()
      cy.wait(3000)
      cy.get('div.ag-header-cell[col-id="field__bit_size"]').click()
      cy.wait(3000)
  
      // Assert that the descending sort class appears.
      cy.get('div[col-id="field__bit_size"]')
        .find('.ag-cell-label-container')
        .should('have.class', 'ag-header-cell-sorted-desc')
  
      // Assert that the ascending sort icon is visible.
      cy.get('div[col-id="field__bit_size"]')
        .find('.ag-sort-descending-icon')
        .should('not.have.class', 'ag-hidden')
  
      // Assert that the URL contains the correct sort parameter.
      cy.url().should('include', '?sort-by=field-bit-size_desc')
  
      // Verify the sorting order is correct by comparing adjacent cell values.
      // First get all cells in the Bit Size column
      cy.get('div[col-id="field__bit_size"][role="gridcell"]').then(($cells) => {
        if ($cells.length >= 2) {
          for (let i = 0; i < $cells.length - 1; i += 1) {
            // Extract the numeric values safely
            const currentText = $cells.eq(i).find('.ag-cell-value').text().trim();
            const nextText = $cells.eq(i + 1).find('.ag-cell-value').text().trim();
  
            const currentValue = isNaN(parseInt(currentText, 10)) ? 0 : parseInt(currentText, 10);
            const nextValue = isNaN(parseInt(nextText, 10)) ? 0 : parseInt(nextText, 10);
  
            // Check that current value is less than or equal to the next value
            expect(currentValue).to.be.at.least(nextValue);
          }
        }
      })
    })
  
    it('(WW2-15976-09) User can hide columns', { tags: ['product-tables-ag-grid', 'WW2-15976', 'WW2-15976-09', 'mlit', 'anonymous'] }, () => {
      // Access the product page
      cy.visit('products/microcontrollers-microprocessors/rl78-low-power-8-16-bit-mcus/product-selector')
      cy.waitForParametricTable()
  
      // Get the first column that contains button to hidden it
      cy.get('.ag-header-viewport button.ag-header-cell-hide-button')
        .not('.ag-header-cell-hide-button--hidden')
        .first().as('hideButton')
        .parents('.ag-header-cell')
        .should('be.visible')
        .invoke('attr', 'col-id').as('columnName', { type: 'static' })
  
      // click on the hide button
      cy.get('@hideButton').should('be.visible')
      cy.get('@hideButton').click()
  
      // Expect column to not be visible
      cy.get('@columnName').then((columnName) => {
        cy.get(`.ag-header-cell[col-id="${columnName}"]`).should('not.exist')
      })
    })
  
    it('(WW2-15976-10) User can see tooltips', { tags: ['product-tables-ag-grid', 'WW2-15976', 'WW2-15976-10', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      const tooltipText = {
        en: 'The duration date of a product in the Product Longevity Program (PLP).',
        ja: '長期製品供給プログラム(PLP)製品の有効期間',
        zh: '产品长期供货计划（PLP）中产品的持续供应期限。',
      }
      // Access the product page
      cy.visit('products/microcontrollers-microprocessors/rl78-low-power-8-16-bit-mcus/product-selector')
  
      // Get tooltip selector
      cy.get('.tooltip-icon')
        .not('.ag-header-tooltip-icon--hidden')
        .first()
        .as('tooltipElement')
  
      // Hover over the tooltip icon
      cy.get('@tooltipElement').trigger('mouseover', { force: true })
  
      // Verify the tooltip text appears
      cy.get('@tooltipElement')
        .invoke('attr', 'data-tooltip')
        .should('equal', tooltipText[language])
    })
  })
  
})

