describe('cypress/e2e/renesas.com/product-selection-table/product-selection-special-columns.spec.js', () => {
  
  describe('Product Selection Table', { tags: ['product-tables-ag-grid', 'product-selector-pages'] }, () => {
  
    it('(WW2-15982-07) Column Diagrams', { tags: ['product-tables-ag-grid', 'product-selector-pages', 'WW2-15982-07', 'mlit', 'anonymous'] }, () => {
      cy.visit('/products/analog-products/amplifiers/product-selector')
  
      // Verify CAD Modal is present and user can click on it and see modal
      cy.get('.ag-cell[col-id="diagrams"] a')
        .first()
        .click({ force: true })
  
      cy.get('#rmm2-loader')
        .should('exist').and('have.class', 'is-open')
      // User can close the modal by clicking on the “x” icon
      cy.get('.rmm2__close').click()
  
    })
  
    it('(WW2-15982-06) Column Longevity (PLP)', { tags: ['product-tables-ag-grid', 'product-selector-pages', 'WW2-15982-06', 'mlit', 'anonymous'] }, () => {
      cy.visit('/products/microcontrollers-microprocessors/ra-cortex-m-mcus/product-selector')
  
      // a.Verify Dual slider filter is shown and user can filter out values such as —, TBD, 2037
      cy.get('.ag-header-cell[aria-colindex="5"] .ag-floating-filter-button-button').click()
  
      // Verify that the filter dialog appears
      cy.get('.ag-filter').should('be.visible')
      cy.get('.agr-cf-minmax__slider').should('be.visible')
  
      // Test case 1: Default position should show all values including "—"
      cy.get('.ag-cell[aria-colindex="5"]').should('contain', '—') // Should contain dash
  
      // Reopen filter
      cy.get('.ag-header-cell[aria-colindex="5"] .ag-floating-filter-button-button').click()
  
      // Test case 2: Move slider to position 1 - should filter out "—" but show "TBD"
      cy.get('.range-slider__thumb[data-lower]')
        .as('slider')
        .focus()
      cy.get('@slider').type('{rightarrow}', { force: true }) // Move right once
  
      cy.get('.range-slider__thumb[data-lower]')
        .should('have.attr', 'aria-valuenow', '1') // Verify position is 1
  
      // Verify "—" is filtered out but "TBD" is visible
      cy.get('.ag-cell[aria-colindex="5"]').each(($cell) => {
        const cellText = $cell.text().trim()
        expect(cellText).not.to.equal('—')
      })
      cy.get('.ag-cell[aria-colindex="5"]').should('contain', 'TBD')
  
      // Reopen filter
      cy.get('.ag-header-cell[aria-colindex="5"] .ag-floating-filter-button-button').click()
  
      // Test case 3: Move slider to position 2 - should filter out both "—" and "TBD", show "2037"
      cy.get('@slider').focus()
      cy.get('@slider').type('{rightarrow}', { force: true }) // Move right once more (total of 2)
  
      cy.get('.range-slider__thumb[data-lower]')
        .should('have.attr', 'aria-valuenow', '2') // Verify position is 2
  
      // Verify both "—" and "TBD" are filtered out but "2037" is visible
      cy.get('.ag-cell[aria-colindex="5"]').each(($cell) => {
        const cellText = $cell.text().trim()
        expect(cellText).not.to.be.oneOf(['—', 'TBD'])
      })
      cy.get('.ag-cell[aria-colindex="5"]').should('contain', '2037')
  
      // b. Verify that only for this parameter user is not able
      // to enter values manually, only use slider
      cy.get('.agr-cf-minmax__min').should('be.disabled')
      cy.get('.agr-cf-minmax__max').should('be.disabled')
    })
  
  })
  
})

