        cy.get('.ag-virtual-list-item')
          .should('have.length', 1)
  
        cy.get('.ag-virtual-list-item')
          .find('.ag-column-select-column-label')
          .should('have.text', dataTest[currentLang].diagrams)
  
        // eslint-disable-next-line max-len
        // User can select/unselect columns returned in the result and click to Reset Columns after that
        cy.get('.ag-virtual-list-item')
          .find('.ag-column-select-checkbox')
