      // Access the 'Check Product Availability' page
      // Create an alias for the get sample option
      cy.visit('sample-buy/check-inventory')
      cy.intercept('POST', '**/sample-buy/check-inventory/result?partno=**').as('getSample')
  
      // Filter by part number
      cy.get('#edit-partno').type(orderablePartNumber, { force: true })
      cy.get('#edit-data').click({ force: true })
  
      // Expect to be redirected to the 'Product Availability Results' page
      // Expect each result to contain the part number
