describe('cypress/e2e/renesas.com/sample-cart/sample-cart_rore-files.spec.js', () => {
  
  describe('Sample Cart - Destructive tests', { tags: ['sample-request'] }, () => {
  
    // Import test data fixture
    // eslint-disable-next-line camelcase,global-require
      // eslint-disable-next-line camelcase
    const { testCases } = ww2_11621_sampleCartRoreScenarios
    const successMsg = ['Thank you for submitting your Renesas sample request.', 'Your request number is']
  
    testCases.forEach(({
      partNumber, address, id,
      // eslint-disable-next-line camelcase
      production_in_china_q1, production_in_china_q2
    }) => {
      // Create about 5 Sample requests with different parts
      // and different Customer and Shipping addresses.
      it(`(WW2-11621-${id}) User can verify RORE File content with ${partNumber} in ${address.country}`, { tags: ['sample-request', 'WW2-11621', 'admin', 'destructive'] }, () => {
        cy.cleanSampleRequest()
        cy.intercept('POST', '**/sample-request/checkout?t=**&ajax_form=1&_wrapper_format=drupal_ajax**').as('loadCountryProvince')
  
        cy.login(Cypress.env('account').admin)
        cy.visit('/admin/config/renesas/sample/rore-settings')
  
        // Set sample request threshold to 0
        cy.get('#edit-threshold').as('threshold').scrollIntoView()
        cy.get('@threshold').clear()
        cy.get('@threshold').type('0', { force: true })
        cy.get('#edit-submit').click({ force: true })
  
        // Create a sample request with a given part number
        cy.visit('sample-request')
        cy.get('#edit-lookup-query').type(partNumber, { force: true })
        cy.get('#edit-add-to-cart').click({ force: true })
        cy.get('#edit-checkout').click({ force: true })
  
        // Fill in form fields
        cy.get('#edit-channel').select(1, { force: true })
        cy.get('#edit-ref-code').as('editRefCode').clear({ force: true })
        cy.get('@editRefCode').type('N/A', { force: true })
        cy.get('#edit-program-name').as('programName').clear({ force: true })
        cy.get('@programName').type('Test', { force: true })
        cy.get('#edit-target-application').select('Automotive', { force: true })
        cy.get('#edit-end-product').select('Seat', { force: true })
        cy.get('#edit-estimate').as('inputEstimate').clear({ force: true })
        cy.get('@inputEstimate').type(1234, { force: true })
        cy.get('#edit-production-in-china-q1').select(production_in_china_q1, { force: true })
        cy.get('#edit-production-in-china-q2').select(production_in_china_q2, { force: true })
  
        // Contact information fields
        cy.get('#edit-contact-info-email').as('inputEmail').clear({ force: true })
        cy.get('@inputEmail').type(`renesaswebdev+11621_0${id}@gmail.com`, { force: true })
        cy.get('#edit-contact-info-company').as('inputInfoCompany').clear({ force: true })
        cy.get('@inputInfoCompany').type('Renesas', { force: true })
        cy.get('#edit-contact-info-phone').as('inputPhone').clear({ force: true })
        cy.get('@inputPhone').type(1234567890, { force: true })
  
        // Company fields
        cy.get('#edit-company-name').as('inputCompany').clear({ force: true })
        cy.get('@inputCompany').type('Test - Company Name', { force: true })
        cy.get('#edit-company-website').as('inputCompanyWeb').clear({ force: true })
        cy.get('@inputCompanyWeb').type('N/A', { force: true })
  
        // Country and address selectors
        cy.get('#edit-company-address-country-code--2').select(address.country, { force: true })
        cy.get('[data-drupal-selector=edit-company-address-locality]').as('localityInput')
        cy.get('[data-drupal-selector=edit-company-address-administrative-area]').as('administrativeInput')
  
        // Handle special cases for country-specific fields
        if (['Germany'].includes(address.country)) {
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
          cy.get('@localityInput').clear({ force: true })
          cy.get('@localityInput').type(address.city, { force: true })
        }
        if (['Taiwan'].includes(address.country)) {
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
          cy.get('@administrativeInput').select(address.admin_area, { force: true })
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
          cy.get('@localityInput').select(address.city, { force: true })
        }
        if (['Japan'].includes(address.country)) {
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
          cy.get('@administrativeInput').select(address.admin_area, { force: true })
          cy.get('@localityInput').clear({ force: true })
          cy.get('@localityInput').type(address.city, { force: true })
        }
        if (['India'].includes(address.country)) {
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
          cy.get('@administrativeInput').select(address.admin_area, { force: true })
          cy.get('@localityInput').clear({ force: true })
          cy.get('@localityInput').type(address.city, { force: true })
        }
  
        if (address.admin_area && !['Taiwan', 'Japan', 'India'].includes(address.country)) {
          cy.get('@administrativeInput').select(address.admin_area, { force: true })
        }
  
        // Postal code and address line
        cy.get('[data-drupal-selector=edit-company-address-postal-code]').as('postalCode').clear({ force: true })
        cy.get('@postalCode').type(address.postal_code, { force: true })
        cy.get('[data-drupal-selector=edit-company-address-address-line1]').as('address-line1').clear({ force: true })
        cy.get('@address-line1').type('Test Street', { force: true })
  
        // Check same-as options
        cy.get('[name="delivery_info[shipping_contact_info][same_as_contact_information]"]').check({ force: true })
        cy.get('[name="delivery_info[shipping_address][same_as_company_address]"]').check({ force: true })
        // Reviewlisted address
        if (['Germany', 'Taiwan', 'Japan', 'India'].includes(address.country)) {
          cy.wait('@loadCountryProvince').its('response.statusCode').should('eq', 200)
        }
        // Handle ECF section visibility and fields
        cy.get('#edit-ecf').then(($eccSection) => {
          if ($eccSection.css('style') !== 'display: none;') {
            cy.get('#edit-ecf-ecf-wrapper-ecf-parent-company-website').type('N/A', { force: true })
            cy.get('#edit-ecf-ecf-wrapper-ecf-is-military-use').select('0', { force: true })
            cy.get('#edit-ecf-ecf-wrapper-ecf-business-purpose').type('Test Renesas ', { force: true })
          }
        })
  
        // Submit Sample Request.
        cy.get('#edit-checkout').click({ force: true })
        // Verify that the Request ID number has been generated for later use.
        cy.get('#block-kachow-mainpagecontent').should('contain', successMsg[0]).and('contain', successMsg[1])
  
        // Capture request number for later verification
        cy.get('.idt-sample-cart-checkout-form__wrapper strong')
          .invoke('text')
          .then((requestNumber) => {
            cy.wrap(requestNumber.trim()).as('requestNumber')
          })
  
        // Generate RORE file with the captured request number
        cy.visit('/admin/config/renesas/sample/rore-files')
        cy.get('#edit-generate-rore-files').click({ force: true })
  
        cy.get('@requestNumber').then((number) => {
          cy.get('input[id="edit-sample-request-id"]').type(number, { force: true })
        })
        cy.get('#edit-submit').click({ force: true })
  
        // Verify RORE file content and modal details
        cy.get('@requestNumber').then((requestNumber) => {
          cy.get('#results-wrapper table tbody tr').contains('td', requestNumber).parents('tr')
            .within(() => {
              cy.contains('a', 'View file').click({ force: true })
            })
        })
        // Open the modal and check the content
        // Verify that the request number is in the View RORE file.
        cy.get('#drupal-modal').as('modalRore').should('exist').and('be.visible')
        cy.get('@requestNumber').then((requestNumber) => {
          const expectedEmail = `renesaswebdev+11621_0${id}@gmail.com`
          const expectedPhone = '1234567890'
          const expectedCompany = 'Renesas'
          const expectedAddress = 'Test Street'
          const expectedProgramName = 'Test'
          // Verify that the RORE file modal contains the associated request number information.
          cy.get('@modalRore').should('contain.text', requestNumber)
          cy.get('@modalRore').should('contain.text', expectedEmail)
          cy.get('@modalRore').should('contain.text', expectedPhone)
          cy.get('@modalRore').should('contain.text', expectedCompany)
          cy.get('@modalRore').should('contain.text', expectedAddress)
          cy.get('@modalRore').should('contain.text', expectedProgramName)
        })
  
      })
    })
  })
  
})

