describe('cypress/e2e/renesas.com/search/global/filter-pills.spec.js', () => {
  
  describe('Global Search', { tags: ['global-search'] }, () => {
    const keyword = 'wireless'
    const pills = {
      en: {
        name: {
          1: 'Products',
          2: 'Datasheet',
          3: 'User Manual',
          4: 'Documents',
          5: 'Boards & Kits',
          6: 'Software & Tools',
          7: 'Videos',
          8: 'FAQ',
          9: 'Support Forums',
          10: 'CS+ Support',
        }
      },
      ja: {
        name: {
          1: '製品',
          2: 'データシート',
          3: 'ユーザマニュアル',
          4: '技術資料',
          5: 'ボード＆キット',
          6: 'ソフトウェア／ツール',
          7: 'ビデオ',
          8: 'よくあるご質問(FAQ)',
          9: 'サポートフォーラム',
          10: 'CS+サポート',
        }
      },
      zh: {
        name: {
          1: '产品',
          2: '数据手册',
          3: '用户手册',
          4: '文档',
          5: '开发板与套件',
          6: '软件与工具',
          7: '视频',
          8: '常见问题',
          9: '支持论坛',
          10: 'CS+ 支持',
        }
      },
    }
    const filterText = {
      en: 'Datasheet',
      ja: 'データシート',
      zh: '数据手册',
    }
  
    it('(WW2-11659-14) User can see all filter-pills with correct ordering and translations', { tags: ['global-search', 'algolia', 'WW2-11659', 'WW2-11659-14', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      const expectedNames = Object.values(pills[language].name)
  
      // Access global search filtering by keyword
      // Wait for page to load
      cy.visit(`search?keywords=${keyword}`)
      cy.waitGlobalSearchLoading()
  
      // Expect filter pills to be visible
      // expect each filter pill to have correct order and title
      cy.get('.ais-pills-list').should('exist').and('be.visible')
      cy.get('.asp__pills .ais-pills-label').each(($label) => {
        const actualText = $label.text().trim()
        expect(expectedNames).to.include(actualText)
      })
    })
  
    it('(WW2-11659-15) user can click on the pill and have correct filter result (related to the selected pill)', { tags: ['global-search', 'algolia', 'WW2-11659', 'WW2-11659-15', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      // Open the global search page
      cy.openGlobalSearchPage()
  
      cy.get('#autocomplete-0-input').as('autocompleteSearch').should('exist').and('be.visible')
      cy.get('@autocompleteSearch').type(keyword, { force: true })
      cy.get('@autocompleteSearch').type('{enter}')
      cy.get('@autocompleteSearch').should('have.value', keyword)
      cy.get('.ais-pills-list').should('exist').and('be.visible')
  
      cy.get('.ais-Menu-label.ais-pills-label')
        .contains(filterText[language])
        .parents('a.ais-Menu-link.ais-pills-link')
        .click()
  
      cy.get('#asp__hits').should('exist').and('be.visible')
  
      // Ensure that the list of hits is loaded
      cy.get('#asp__hits .ais-Hits-list li').should('have.length.at.least', 1)
  
      /**
       * After the click, ensure that all <li> elements within .ais-Hits-list
       * have "Datasheet" inside the div with class 'asr__eyebrow'
       */
      cy.get('#asp__hits .ais-Hits-list li').each(($li) => {
        // Use cy.wrap to handle re-rendering issues
        cy.wrap($li)
          .find('.asr__eyebrow')
          .should('contain', filterText[language])
      })
    })
  
    it('(WW2-11659-16) Verify “x” icon appears on the selected pills and disappears when user unselect the pill by clicking on it', { tags: ['global-search', 'algolia', 'WW2-11659', 'WW2-11659-16', 'mlit', 'anonymous'] }, () => {
      // Open the global search page
      cy.openGlobalSearchPage()
  
      cy.get('#autocomplete-0-input').as('autocompleteSearch').should('exist').and('be.visible')
      cy.get('@autocompleteSearch').type(keyword, { force: true })
      cy.get('@autocompleteSearch').type('{enter}')
      cy.get('@autocompleteSearch').should('have.value', keyword)
      cy.get('.ais-pills-list').should('exist').and('be.visible')
  
      // Assert that initially the class ais-Menu-item--selected does not exist
      cy.get('.ais-Menu-item--selected').should('not.exist')
  
      // Click on the first menu item
      cy.get('.ais-Menu-item').first().find('.ais-Menu-link').click({ force: true })
  
      // Assert that the class ais-Menu-item--selected has been added to the first menu item
      cy.get('.ais-Menu-item').first().should('have.class', 'ais-Menu-item--selected')
  
      // Click on the first menu item again
      cy.get('.ais-Menu-item').first().find('.ais-Menu-link').click({ force: true })
  
      // Assert that the class ais-Menu-item--selected has been removed from the first menu item
      cy.get('.ais-Menu-item').first().should('not.have.class', 'ais-Menu-item--selected')
  
    })
  
    it('(WW2-11659-17) Verify that filter pills are not shown if there is no result found', { tags: ['global-search', 'algolia', 'WW2-11659', 'WW2-11659-17', 'mlit', 'anonymous'] }, () => {
      // Open the global search page
      const noResultsKeyword = 'ghghghghghhhhk'
  
      cy.openGlobalSearchPage()
  
      cy.get('#autocomplete-0-input').should('exist').and('be.visible')
      cy.get('#autocomplete-0-input').type(noResultsKeyword, { force: true })
      cy.get('#autocomplete-0-input').type('{enter}')
      cy.get('.asp .asp__no-results').should('exist').and('be.visible').should('contain', `"${noResultsKeyword}"`)
      cy.get('.ais-pills-list .ais-Menu-item').should('not.exist')
    })
  })
  
})

describe('cypress/e2e/renesas.com/search/global/loading-indicators.spec.js', () => {
  
  describe('Global Search', { tags: ['global-search'] }, () => {
  
    const testData1 = {
      en: {
        loadingMessage: 'Loading',
      },
      ja: {
        loadingMessage: '読込中',
      },
      zh: {
        loadingMessage: '加载中',
      },
    }
  
    it('(WW2-12429-03) User should see loading indicator before content appears when there is a delay', { tags: ['global-search', 'algolia', 'WW2-12429', 'WW2-12429-03', 'mlit', 'anonymous'] }, () => {
  
      const { loadingMessage } = testData1[cy.config('language')]
      const keyword = 'software'
  
      // Open autocomplete search
      // Search by keyword
      cy.visit('')
      cy.get('#block-kachow-algoliapresearchblock .search-link > a').click({ force: true })
      cy.get('#autocomplete-0-input').as('autocompleteSearch').should('exist').and('be.visible')
      cy.get('@autocompleteSearch').type(keyword, { force: true })
      cy.get('@autocompleteSearch').click({ force: true })
  
      // Intercept the search results and add a delay to its response
      cy.intercept({ method: 'POST', pathname: '**/api/search/*/*/indexes/**' }, (req) => {
        return Cypress.Promise.delay(3000).then(() => { return req.continue() })
      }).as('searchResults')
  
      // Type {enter} in autocomplete to search the results
      cy.get('@autocompleteSearch').type('{enter}')
  
      /**
       * Expect loading indicator:
       *  - to have correct text
       *  - to be visible
       */
      cy.get('.asp').should('have.class', 'is-loading').within(() => {
        cy.get('.asp__loading-indicator').as('loadingIndicator2').should('be.visible')
        cy.get('.info-text').should('exist').and('be.visible').and('contain', loadingMessage)
      })
  
      // Add wait for the loading indicator to disappear
      cy.wait(2000)
  
      // Expect loading indicator to not be visible
      cy.get('.asp').should('not.have.class', 'is-loading').within(() => {
        cy.get('.asp__loading-indicator').should('not.be.visible')
        cy.get('.info-text').should('not.be.visible')
      })
    })
  
    it('(WW2-12429-04) Verify search results are fading out when perform a new search', { tags: ['global-search', 'algolia', 'WW2-11659', 'WW2-12429', 'WW2-12429-04', 'mlit', 'anonymous'] }, () => {
      // Step 1: Open the global search page
      cy.openGlobalSearchPage()
  
      // Step 2: Perform the initial search and ensure results are loaded
      const keyword = 'initial search term' // Replace with your initial search term
      cy.get('#autocomplete-0-input').as('autocompleteSearch').should('exist').and('be.visible')
      cy.get('@autocompleteSearch').type(keyword, { force: true })
      cy.get('@autocompleteSearch').type('{enter}')
      cy.get('@autocompleteSearch').should('have.value', keyword)
      cy.get('.asp__content').should('have.class', 'asp__content--loaded')
  
      // Step 3: Trigger a new search
      cy.get('.facet-product-category .ais-HierarchicalMenu-list').within(() => {
        cy.get('.ais-HierarchicalMenu-item').first().find('.ais-HierarchicalMenu-link').click({ force: true })
      })
  
      // Step 4: Assert the transition effect
      cy.get('.asp__content')
        .should('have.css', 'opacity', '0.25') // Check for fade-out effect
        .and('not.have.class', 'asp__content--loaded')
  
      // Wait for the transition to complete (250ms + 500ms for the transition)
      cy.wait(750)
  
      // Verify that the results container is fully visible again
      cy.get('.asp__content')
        .should('have.class', 'asp__content--loaded')
        .and('have.css', 'opacity', '1')
    })
  })
  
})

