describe('cypress/e2e/renesas.com/search/global/search-language-display.spec.js', () => {
  
  describe('Global Search', { tags: ['global-search'] }, () => {
  
    const languageDisplay = {
      en: null,
      ja: ['日本語', '中文', '英語'],
      zh: ['中文', '日本語', '英语']
    }
  
    it('(WW2-13141) User should see the translation language displayed in search results', { tags: ['global-search', 'algolia', 'WW2-13141', 'mlit', 'anonymous'] }, () => {
  
      const lang = cy.config('language')
      cy.visit('')
      // Go to autocomplete search
      cy.get('#block-kachow-algoliapresearchblock .search-link > a').click({ force: true })
      cy.get('#autocomplete-0-input').click({ force: true })
      cy.get('#autocomplete-0-input').type('ra2a1', { force: true })
  
      cy.get('.aa-Source[data-autocomplete-source-id="topResults"]').should('be.visible')
      cy.get('.aa-List .aa-Item div')
        .first()
      const langText = languageDisplay[lang]
      cy.get('.asr__content').should('be.visible')
      // Verify it is hidden on the English site.
      if (lang === 'en') {
        cy.get('.asr__language').should('not.exist')
      } else {
        cy.get('.asr__language').first().should('be.visible')
          .scrollIntoView()
          .then(($element) => {
            // Assert that the element contains at least one of the texts in langText
            const text = $element.text();
            expect(langText.some(option => text.includes(option))).to.be.true;
          });
      }
  
      // Go to search results
      cy.get('#autocomplete-0-input').type('{enter}')
      cy.waitGlobalSearchLoading()
      cy.get('#asp__hits').should('exist').and('be.visible').scrollIntoView()
      // Verify it is hidden on the English site.
      if (lang === 'en') {
        cy.get('#asp__hits .ais-Hits-list li .asr__content .asr__forehead .asr__language')
          .should('not.exist')
      } else {
        cy.get('#asp__hits .ais-Hits-list li .asr__content .asr__forehead .asr__language')
          .each(($li) => {
            cy.wrap($li).scrollIntoView()
              .then(($element) => {
                const text = $element.text();
                expect(langText.some(option => text.includes(option))).to.be.true;
              });
          });
      }
    })
  })
  
})

