describe('cypress/e2e/renesas.com/search/software-tools-search.spec.js', () => {
  
  describe('Software & Tools Search', { tags: ['algolia'] }, () => {
  
    const testData1 = {
      en: {
        softwareType: 'File System',
        developmentType: 'Code Generator',
        noResultsMessage: 'Search has returned no results'
      },
      ja: {
        softwareType: 'ファイルシステム',
        developmentType: 'コードジェネレータ',
        noResultsMessage: '検索結果がありませんでした'
      },
      zh: {
        softwareType: '文件系统',
        developmentType: '代码生成器',
        noResultsMessage: '没有搜索结果'
      }
    }
  
    it('(WW2-7920) User should see no results message when search or filtering yields no results', { tags: ['algolia', 'WW2-7920', 'mlit', 'anonymous'] }, () => {
      const keyword = 'asdfqwerty'
      const { noResultsMessage } = testData1[cy.config('language')]
  
      // Access the software search page
      // Wait page to finish loading
      cy.visit('support/software-search')
      cy.waitAlgoliaLoading()
  
      // Enter Random Part Number and Search
      cy.get('#edit-doc-part-numbers').type(keyword, { force: true })
      cy.get('#edit-search').click({ force: true })
  
      // Wait page to finish loading
      // Expect search to yield results
      cy.waitAlgoliaLoading()
      cy.get('.table-group-wrapper').should('exist').and('be.visible').within(() => {
        cy.get('tbody tr').should('contain', noResultsMessage)
      })
    })
  
    it('(WW2-7900) User can search for software & tools by title, category, part number and type', { tags: ['algolia', 'WW2-7900', 'mlit', 'anonymous'] }, () => {
      const categoryNodeId = '467666'
      const subCategoryNodeId = '469301'
      const { softwareType } = testData1[cy.config('language')]
      const { developmentType } = testData1[cy.config('language')]
      const title = 'FAT'
      const partNumber = '5X1503S-000NLGI'
      const commonCategoryKeyword = 'RH850'
      let totalNumbResults
  
      // Access the software search page
      // Wait page to finish loading
      cy.visit('support/software-search')
      cy.waitAlgoliaLoading()
  
      // Save the total number of results
      cy.get('.table-group-wrapper tbody tr').as('tableResults').then(($totalNumberResults) => {
        totalNumbResults = $totalNumberResults.length
      })
  
      // Select Software Type filter
      // Enter a Title
      // Click on search
      cy.get('#software-type-0-91--label').as('softwareTypeCheckbox').click({ force: true })
      cy.get('#edit-keywords').as('titleSearchField').type(title, { force: true })
      cy.get('#edit-search').as('searchButton').click({ force: true })
  
      // Wait for results to load
      // Expect each result to contain keyword and software type
      cy.waitAlgoliaLoading()
      cy.get('@tableResults').should('be.visible').each(($typeResults) => {
        cy.get($typeResults).should('contain', title)
        cy.get($typeResults).should('contain', softwareType)
      })
  
      // Expect total number of results to be greater than the number of filtered results
      cy.get('@tableResults').then(($filteredNumberResults) => {
        expect(totalNumbResults).to.be.greaterThan($filteredNumberResults.length)
      })
  
      // Clear the title field
      // Uncheck software type option
      cy.get('@titleSearchField').clear({ force: true })
      cy.get('@softwareTypeCheckbox').click({ force: true })
  
      // Select Development Tool Type filter
      // Enter a Part number
      cy.get('#software-type-1-56--label').as('developToolTypeCheckbox').click({ force: true })
      cy.get('#edit-doc-part-numbers').as('partNumberSearchField').type(partNumber, { force: true })
      cy.get('@searchButton').click({ force: true })
  
      // Wait for results to load
      // Expect each result to contain keyword and development tool type
      cy.waitAlgoliaLoading()
      cy.get('@tableResults').each(($typeResults) => {
        cy.get($typeResults).should('contain', developmentType)
      })
  
      // Expect total number of results to be greater than the number of filtered results
      cy.get('@tableResults').then(($filteredNumberResults) => {
        expect(totalNumbResults).to.be.greaterThan($filteredNumberResults.length)
      })
  
      // Development Tool Type filter
      // Clear the part number field
      cy.get('@developToolTypeCheckbox').click({ force: true })
      cy.get('@partNumberSearchField').clear({ force: true })
  
      // Select Category Filters
      // Wait for sub-category field to load
      // Select sub-category
      // Click on search
      cy.get('#edit-doc-category-tier-1').select(categoryNodeId, { force: true })
      cy.get('#edit-doc-category-tier-2').as('subcategoryField').should('exist').and('be.visible')
      cy.get('@subcategoryField').select(subCategoryNodeId, { force: true })
      cy.get('@searchButton').click({ force: true })
  
      // Wait for results to load
      // Expect results to contain the common keyword
      cy.waitAlgoliaLoading()
      cy.get('@tableResults').should('contain', commonCategoryKeyword)
  
      // Expect total number of results to be greater than the number of filtered results
      cy.get('@tableResults').then(($filteredNumberResults) => {
        expect(totalNumbResults).to.be.greaterThan($filteredNumberResults.length)
      })
    })
  })
  
})

describe('cypress/e2e/renesas.com/secure-access/secure-access_1.spec.js', () => {
  
  describe('Secure Access', { tags: ['secure-access-documents'] }, () => {
  
    const testData1 = {
      en: {
        email: 'Email address',
        password: 'Password',
        forgot_password: 'Forgot password?',
        login: 'Log In',
        register: 'Register',
        download: 'Log in to Download'
      },
      ja: {
        email: 'メールアドレス',
        password: 'パスワード',
        forgot_password: 'パスワードをお忘れですか？',
        login: 'ログイン',
        register: '登録',
        download: 'ログインしてダウンロード'
      },
      zh: {
        email: '电子邮件地址',
        password: '密码',
        forgot_password: '忘记密码？',
        login: '登录',
        register: '注册',
        download: '登录后下载'
      }
    }
  
    it('(WW2-T995) Anonymous user cannot access restricted document (url link)', { tags: ['secure-access-documents', 'WW2-3339', 'WW2-T995', 'mlit', 'anonymous'] }, () => {
  
      const { login } = testData1[cy.config('language')]
      const { email } = testData1[cy.config('language')]
      const { password } = testData1[cy.config('language')]
  
      /**
       * Cypress sometimes fails when visiting the document
       * because of the content-type of the response.
       * We need to override the user agent to avoid this issue
       */
      if (cy.browserIsHeadlessChrome()) {
        cy.overrideUserAgent()
      }
  
      // Try to access a protected document
      cy.visit('document/err/tsi721-device-errata')
  
      // Expect to see login page and login fields
      cy.get('#edit-username').should('exist').and('be.visible').parent().should('contain', email)
      cy.get('#edit-password').should('exist').and('be.visible').parent().should('contain', password)
      cy.get('#edit-reset-password').should('exist').and('be.visible')
      cy.get('#edit-submit').should('exist').and('be.visible').and('contain', login)
      cy.get('.register-link').should('exist').and('be.visible')
      cy.url().should('contain', '/oauth2/default/v1/authorize')
    })
  
    it('(WW2-14278) Anonymous and registered user cannot access archived document', { tags: ['secure-access-documents', 'WW2-14278', 'mlit', 'authenticated'] }, () => {
  
      // Access archived document
      cy.visit('document/prr/r7f0e01xxxxfp-reliability-report')
  
      // Expect to be redirected to the login page
      cy.get('#edit-username').should('exist').and('be.visible')
      cy.get('#edit-password').should('exist').and('be.visible')
  
      // Log in as authenticated user
      cy.fillInLoginForm(Cypress.env('account').authenticated)
  
      // Expect to see 403 page
      cy.get('h1').should('contain', '403 Error')
    })
  
    it('(WW2-T922-01) Anonymous user cannot access restricted document (documentation table)', { tags: ['secure-access-documents', 'generic-product-documentation-tab', 'WW2-4303', 'WW2-T922-01', 'mlit', 'anonymous'] }, () => {
  
      const { login } = testData1[cy.config('language')]
      const { download } = testData1[cy.config('language')]
  
      // Access product page
      // Wait for documentation table to load
      cy.visit('products/zssc4165?tab=documentation')
      cy.waitForDocumentationLazyload()
  
      /**
       * Some user agents are allowed direct access to files
       * The following command modifies it to prevent the agent to access the file
       */
      if (cy.browserIsHeadlessChrome()) {
        cy.overrideUserAgent()
      }
  
      // Find and click the first "Log in to Download" link inside asr__meta
      cy.get('.documentation-search__hits-groups .asr__meta a.document-link.document-link-loaded')
        .contains(download)
        .first()
        .should('have.class', 'document-link-loaded', { timeout: 80000 })
        .click({ force: true })
  
      // Stub window.open so the link opens in the same tab (optional)
      cy.window().then((win) => {
        cy.stub(win, 'open', (url) => {
          win.location.href = url
        }).as('newTab')
      })
  
      // Confirm the DUNS pops up
      cy.get('#rmm-dun-modal').should('have.attr', 'aria-hidden', 'false').and('have.class', 'is-open')
      cy.get('.dun-options [value="0"]').check({ force: true })
      cy.get('.submit').click({ force: true })
  
      // Expect to be redirected to the login page
      cy.get('@newTab').should('be.called')
      cy.contains(login)
      cy.get('@newTab').url().should('contain', '/oauth2/default/v1/authorize')
    })
  
    it('(WW2-10515) Secure documents node form must have pink background and lock icon', { tags: ['cms', 'secure-access-documents', 'WW2-10515', 'mlit', 'admin', 'destructive'] }, () => {
      // Log in as admin.
      cy.login(Cypress.env('account').admin)
  
      // Visit a secure document edit page
      cy.visit('node/25426311/edit')
  
      // Check lock exists and is visible
      cy.get('h1.page-title .lock').should('exist').and('be.visible')
      // Verify the warning message is showing
      cy.get('.messages--warning .messages__content')
        .should('contain', 'This is a secure document. This document belongs to the following secure groups:')
        .and('be.visible')
      // Confirm the background is pink
      cy.get('body .doc-secure-page').should('have.css', 'background-color', 'rgb(250, 229, 233)')
    })
  
    it('(WW2-11204) Users from a secure content group can access restricted documents associated with their group', { tags: ['secure-access-documents', 'document-management', 'WW2-11204', 'authenticated', 'destructive'] }, () => {
      // Document is restricted to 'Renesas Employees'
      const secureDocumentUrl = 'document/sch/rc32614-evaluation-board-schematic'
      const secureDocumentTitle = 'R-Car S4 SDK download guide material'
      const secureDocumentNodeID = '25412306'
  
      // Log in with user that IS NOT in the secure group
      // Access the secure document
      cy.login(Cypress.env('account').authenticated)
      cy.visit(secureDocumentUrl)
  
      // Expect to land on the 'Request Access' page
      cy.get('h1').should('contain', 'Secure Access Request')
      cy.url().should('contain', '/request-access/')
  
      // Log out
      // Log in with user that IS in the secure group
      cy.logout()
      cy.login(Cypress.env('account').whitelisted)
  
      // Access the document search filtered by the document's title
      // Clear the part number field and click on search to avoid a cache issue
      cy.visit(`support/document-search?keywords=${secureDocumentTitle}&page=0`)
      cy.waitAlgoliaLoading()
      cy.get('#edit-doc-part-numbers').clear({ force: true })
      cy.get('#edit-search').click({ force: true })
      cy.waitAlgoliaLoading()
  
      // Create alias for the document page to open
      cy.window().then((win) => {
        cy.stub(win, 'open', (url) => {
          win.location.href = url
        }).as('documentPage')
      })
  
      // Click to open the document
      // Confirm DUNs pop-up
      // Expect document to open
      cy.get(`a[data-doc="${secureDocumentNodeID}"]`).should('have.class', 'document-link-loaded').click({ force: true })
      cy.get('#dun-modal .submit').click({ force: true })
      cy.get('@documentPage').should('be.called')
      cy.url().should('not.contain', '/request-access/')
    })
  })
  
})

describe('cypress/e2e/renesas.com/secure-access/secure-access_2.spec.js', () => {
  
  describe('Secure Access - Tests that require a user without secure access', { tags: ['secure-access-documents'] }, () => {
  
    const testData1 = {
      en: {
        documentAccessRequest: 'Secure access requested for',
        secureAccessSubmitted: 'Your secure access request has been submitted'
      },
      ja: {
        documentAccessRequest: '認証リクエスト',
        secureAccessSubmitted: 'セキュアアクセスを申請しました'
      },
      zh: {
        documentAccessRequest: '安全访问权限对象',
        secureAccessSubmitted: '您的安全访问请求已提交。'
      }
    }
  
    it('(WW2-T924) User can request and have access granted to secure documents', { tags: ['secure-access-documents', 'WW2-6429', 'WW2-T924', 'authenticated', 'mlit', 'destructive'] }, () => {
  
      const secureAccessTitle = 'Secure Access Request'
      const { secureAccessSubmitted } = testData1[cy.config('language')]
      const secureDocumentNodeId = '25565137'
  
      // Log in as admin
      // Remove all authenticated user's secure access
      cy.login(Cypress.env('account').admin)
      cy.removeUserSecureAccess(Cypress.env('account').authenticated)
  
      // Get the link of the secure document
      // Log out
      cy.visit(`node/${secureDocumentNodeId}/edit`)
      cy.get('#edit-path-0-alias').invoke('val').as('secureDocumentLink', { type: 'static' })
      cy.logout()
  
      /**
       * Cypress sometimes fails when visiting the document
       * because of the content-type of the response.
       * We need to override the user agent to avoid this issue
       */
      if (cy.browserIsHeadlessChrome()) {
        cy.overrideUserAgent()
      }
  
      // Anonymous user tries to access a restricted document
      // Login as an authenticated user
      cy.get('@secureDocumentLink').then((secureDocumentLink) => {
        cy.visit(secureDocumentLink)
      })
      cy.fillInLoginForm(Cypress.env('account').authenticated)
  
      /**
       * Expect:
       *  - User to be on the request secure access page
       *  - Document link to be correct
       */
      cy.url().should('contain', `/request-access/${secureDocumentNodeId}`)
      cy.get('@secureDocumentLink').then((secureDocumentLink) => {
        cy.get('#edit-sar-node-access-request').invoke('val').should('contain', secureDocumentLink)
      })
  
      // Click to submit secure access request
      // Expect to see confirmation message
      // Log out of the page
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages').should('contain', secureAccessSubmitted)
      cy.logout()
  
      // Log in as admin to accept the secure access request
      cy.login(Cypress.env('account').admin)
  
      // Access the Secure Access Request Management page
      // Expect to see authenticated user request
      // Click to process the request
      cy.visit('admin/content/sar?name=qa%20authenticated')
      cy.get('#toolbar-item-administration-tray').should('exist').and('be.visible')
      cy.get('#edit-sar-id tbody tr').should('have.length', 1).then(($request) => {
        cy.get($request).should('contain', Cypress.env('account').authenticated.username)
        cy.get($request).find('td a').last().click({ force: true })
      })
  
      // Expect user's info to be correct
      // Expect document link to be correct
      cy.get('.block-page-title-block').should('contain', secureAccessTitle)
      cy.get('#idt-secure-access-process-form div p').should('contain', Cypress.env('account').authenticated.username)
      cy.get('@secureDocumentLink').then((secureDocumentLink) => {
        cy.get('#edit-user-requests tbody tr a').should('contain', secureDocumentLink)
      })
  
      // Click to grant the user access to the document
      // Log out of the page
      cy.get('#edit-user-group-options a').first().click({ force: true })
      cy.url().should('contain', '/sar/action/grant')
      cy.get('#edit-submit').click({ force: true })
      cy.url().should('contain', '/admin/content/sar', { timeout: 120000 })
      cy.logout()
  
      // Access the document page
      // Login as an authenticated user
      cy.get('@secureDocumentLink').then((secureDocumentLink) => {
        cy.visit(secureDocumentLink, { failOnStatusCode: false })
      })
      cy.get('#edit-username').type(Cypress.env('account').authenticated.username, { force: true })
      cy.get('#edit-password').type(Cypress.env('account').authenticated.password, { log: false, force: true })
      cy.get('#edit-submit').click({ force: true })
  
      // Expect to see document page (if browser is not headless chrome)
      cy.get('embed').should('be.visible')
    })
  
    it('(WW2-T948) Authenticated user can request access to restricted document', { tags: ['secure-access-documents', 'WW2-3339', 'WW2-T948', 'authenticated', 'mlit', 'destructive'] }, () => {
  
      const language = cy.config('language')
      const secureDocumentLink = 'document/dst/iw1822-datasheet'
      const secureDocumentNodeId = '1549066'
      const { documentAccessRequest } = testData1[language]
  
      // Log in as admin
      // Remove all authenticated user's secure access
      // Log out
      cy.login(Cypress.env('account').admin)
      cy.removeUserSecureAccess(Cypress.env('account').authenticated)
      cy.logout()
  
      // Log in as Authenticated user
      cy.login(Cypress.env('account').authenticated)
  
      // The disclaimer may be skipped depending on user agent.
      // It's a problem for headless chrome.
      if (cy.browserIsHeadlessChrome()) {
        cy.overrideUserAgent()
      }
  
      // Access a secure document
      cy.visit(secureDocumentLink)
  
      // Expect to see the access request page
      // Expect document request to be visible
      cy.url().should('contain', `/request-access/${secureDocumentNodeId}`)
      cy.get('#edit-sar-node-access-request').should('have.value', `/${language}/${secureDocumentLink}`)
        .parent().should('contain', documentAccessRequest)
    })
  })
  
})

