describe('cypress/e2e/renesas.com/sitemap/sitemap.spec.js', () => {
  
  describe('Sitemap', { tags: ['sitemap'] }, () => {
  
    const titles = {
      en: {
        products: 'Products',
        applications: 'Applications',
        designResources: 'Design Resources',
        support: 'Support',
        sampleBuy: 'Sample & Buy',
        about: 'About'
      },
      ja: {
        products: '製品情報',
        applications: 'アプリケーション',
        designResources: '設計リソース',
        support: 'サポート',
        sampleBuy: 'サンプル&ご購入',
        about: '会社情報'
      },
      zh: {
        products: '产品',
        applications: '应用',
        designResources: '设计资源',
        support: '支持',
        sampleBuy: '样品和购买',
        about: '关于我们'
      },
    }
  
    it('(WW2-10118) User cannot see node in search results when it has \'Do not include in sitemap\' option enabled', { tags: ['sitemap', 'WW2-10118', 'mlit', 'admin', 'destructive'] }, () => {
      const nodeID = '1497671'
  
      // Log in as admin
      // Edit the product page
      // Save the product ID
      cy.login(Cypress.env('account').admin)
      cy.visit(`node/${nodeID}/edit`)
      cy.get('#edit-field-product-id-0-value').invoke('val').as('productID', { type: 'static' })
  
      // Expect 'Do not include in Sitemap' option to be enabled
      cy.get('#edit-simple-sitemap-default-index-0').should('be.checked')
  
      // Log out and access the home page
      cy.logout()
      cy.visit('')
  
      // Open autocomplete search
      cy.get('#block-kachow-algoliapresearchblock .search-link > a').click({ force: true })
      cy.get('.aa-LoadingIndicator').should('have.attr', 'hidden')
      cy.get('.aa-Panel').should('exist').and('be.visible')
  
      // Search by product id
      cy.get('@productID').then(($pageTitle) => {
        cy.get('.block-renesas-algolia-presearch-block .search-container .aa-Autocomplete .aa-Form .aa-Input').as('autocompleteField').type($pageTitle, { force: true })
        cy.get('.aa-Panel .aa-List').should('exist').and('be.visible')
      })
  
      // Expect product to not exist in the search results
      cy.get(`[data-insights-object-id="${nodeID}"]`).should('not.exist')
  
      // Access global search page
      cy.get('@autocompleteField').type('{enter}')
      cy.waitGlobalSearchLoading()
  
      // Expect product to not exist in the search results
      cy.get(`[data-nid="${nodeID}"]`).should('not.exist')
    })
  
    it('(WW2-11620-01) Verify sitemap dynamic block display', { tags: ['sitemap', 'paragraphs', 'WW2-11620', 'WW2-11620-01', 'mlit', 'anonymous'] }, () => {
      const language = cy.config('language')
      cy.visit('sitemap')
  
      /**
       * Expect:
       *  - sitemap top level headers displayed
       */
      const topLevelLinks = [
        titles[language].products,
        titles[language].applications
      ]
      topLevelLinks.forEach((item) => {
        cy.contains('#block-sitemap .is-parent.is-level-1 > a', item)
      })
      const topLevelNoLinks = [
        titles[language].designResources,
        titles[language].support,
        titles[language].sampleBuy,
        titles[language].about
      ]
      topLevelNoLinks.forEach((item) => {
        cy.contains('#block-sitemap .grouped-submenus.nav-menu--simple__link', item)
      })
  
      /**
       * Expect:
       *  - Product Categories and Product Subcategories are displayed.
       */
      cy.get('#block-sitemap .is-parent.is-level-1').each(($level1) => {
        const parentLink = $level1.find('a').first().text()
        if (parentLink === titles[language].products || parentLink === titles[language].applications) {
          cy.get($level1).find('.is-parent.is-level-2').each(($level2) => {
            cy.get($level2).find('.is-level-3')
          })
        }
      })
    })
  
    it('(WW2-11620-02) User can add dynamic block display', { tags: ['sitemap', 'paragraphs', 'WW2-11620', 'WW2-11620-02', 'mlit', 'admin', 'destructive'] }, () => {
      const timestamp = Date.now()
      const language = cy.config('language')
      const pageTitle = `Test WW2-11620 - Page - ${language} - ${timestamp}`
      const newPageUrl = 'node/add/page'
  
      cy.login(Cypress.env('account').admin)
      cy.visit(newPageUrl)
  
      cy.intercept({ method: 'POST', pathname: `**/${newPageUrl}**` }).as('searchDuplicateTitle')
      cy.intercept('POST', '**/node/add/page?ajax_form=1&_wrapper_format=**').as('loadDynamicBlock')
  
      // Select page language
      cy.get('#edit-langcode-0-value').select((language === 'zh' ? 'zh-hans' : language))
  
      // Fill in page title field
      cy.get('#edit-title-0-value').type(pageTitle)
      cy.wait('@searchDuplicateTitle').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
  
      // Fill in long title
      cy.get('#edit-field-long-title-0-value').type(pageTitle)
  
      // Click on the Add Dynamic Block button
      // Add a Latest Notices block
      cy.get('#field-paragraphs-dynamic-block-add-more').click()
      cy.get('.ajax-progress').should('not.exist')
      cy.get('[id^="edit-field-paragraphs-widget-0-subform-group-block"] summary').click()
      cy.get('[id^="edit-field-paragraphs-0-subform-field-block-0-plugin-id"]').select('renesas_blocks_sitemap')
      cy.wait('@loadDynamicBlock').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
  
      // Add a custom URL alias
      cy.get('#edit-path-0-pathauto').uncheck({ force: true })
      cy.get('#edit-path-0-alias').should('not.be.disabled').type(`/test-cypress-8795/${timestamp}`, { force: true })
  
      // Click on Save
      cy.get('#edit-submit').click()
  
      /**
       * Expect:
       *  - page title to be correct
       *  - sitemap headers displayed
       */
      cy.get('h1').should('contain', pageTitle)
      const topLevelLinks = [
        titles[language].products,
        titles[language].applications
      ]
      topLevelLinks.forEach((item) => {
        cy.contains('#block-sitemap .is-parent.is-level-1 > a', item)
      })
      const topLevelNoLinks = [
        titles[language].designResources,
        titles[language].support,
        titles[language].sampleBuy,
        titles[language].about
      ]
      topLevelNoLinks.forEach((item) => {
        cy.contains('#block-sitemap .grouped-submenus.nav-menu--simple__link', item)
      })
    })
  })
  
})

