describe('cypress/e2e/renesas.com/sso/sso-external.spec.js', () => {
  
  describe('SSO - External', { tags: ['sso'] }, () => {
  
    it('(WW2-11004) User can log in to \'Renesas Engineering Community\'', { tags: ['sso', 'community', 'WW2-11004', 'authenticated', 'destructive'] }, () => {
  
      /**
       * Note that this test runs on the production site only.
       * It is set as destructive because it does not work when
       * the baseUrl is set to www.renesas.com due to limitations
       * of cy.origin().
       */
  
      cy.intercept('https://community.renesas.com/**', (req) => {
        req.headers['x-rel-com-bypass'] = Cypress.env('communityBotHeader')
      })
  
      // Access login page
      // Add header to to bypass the firewall rules for community.renesas.com
      cy.origin('https://community.renesas.com', () => {
        cy.visit('/login', {
          headers: {
            'x-rel-com-bypass': Cypress.env('communityBotHeader')
          }
        })
      })
  
      // Log in as authenticated
      cy.get('#edit-username').type(Cypress.env('account').authenticated.username, { force: true })
      cy.get('#edit-password').type(Cypress.env('account').authenticated.password, { force: true })
      cy.get('#edit-submit').click({ force: true })
  
      // Click on the account menu
      // Expect 'sign out' option to exist and contain correct text
      cy.get('.internal-link.user').click({ force: true })
      cy.get('.internal-link.logout').should('exist').and('contain', 'Sign out')
    })
  })
  
})

describe('cypress/e2e/renesas.com/sso/sso_1.spec.js', () => {
  
  describe('SSO', { tags: ['sso'] }, () => {
  
    const testData1 = {
      en: {
        wrongEmailMessage: 'Wrong email address or password.',
        emailAlreadyExistsMessage: 'Entered Email Address already exists in the database. Please enter another Email Address.',
        inactiveAccountMessage: 'This email address is associated with an inactive account at Renesas.com'
  
      },
      ja: {
        wrongEmailMessage: 'メールアドレスまたはパスワードが正しくありません。',
        emailAlreadyExistsMessage: '入力されたメールアドレスは既に登録されています。別のメールアドレスをご入力ください。',
        inactiveAccountMessage: 'このメールアドレスは、Renesas.comのアカウントとして無効となっております。'
      },
      zh: {
        wrongEmailMessage: '电子邮件地址或密码不正确。',
        emailAlreadyExistsMessage: '输入的电子邮件地址已经存在于数据库中。请输入另一个电子邮件地址',
        inactiveAccountMessage: '该电子邮件地址与Renesas.com的一个非活动帐户相关联。'
      },
    }
  
    it('(WW2-T746) Inactive user cannot log in to the site', { tags: ['sso', 'graylist-blocklist-registration', 'WW2-4718', 'WW2-T746', 'mlit', 'smoke-test', 'anonymous'] }, () => {
      const { inactiveAccountMessage } = testData1[cy.config('language')]
  
      cy.visit('user/sso-login')
  
      cy.get('input#edit-username').type(Cypress.env('account').blocked.username, { force: true })
      cy.get('input#edit-password').type(Cypress.env('account').blocked.password, { force: true })
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages').should('contain', inactiveAccountMessage)
    })
  
    it('(WW2-T747) User cannot register a new account using an active user email', { tags: ['sso', 'graylist-blocklist-registration', 'WW2-4718', 'WW2-T747', 'mlit', 'anonymous'] }, () => {
  
      // CDN thinks this comes from a bot
      // so we need to add a secret header
      // to get around it on production.
      cy.onProdEnv().then(($onProd) => {
        if ($onProd) {
          cy.intercept('POST', '**/gur/ssoRegisterUser.do**', (req) => {
            req.headers['X-REL-Bypass'] = Cypress.env('prodBotHeader')
          })
        }
      })
  
      const { emailAlreadyExistsMessage } = testData1[cy.config('language')]
      const password = cy.randomString()
  
      cy.visit('register')
      cy.intercept('POST', '**/gur/ssoRegisterUser.do?client_id=**&ajax_form=1&_wrapper_format=drupal_ajax**').as('loadCountry')
  
      cy.get('#edit-email').type(Cypress.env('account').authenticated.username, { force: true })
      cy.get('#edit-email-confirm').type(Cypress.env('account').authenticated.username, { force: true })
      cy.get('#edit-password-pass1').type(password, { force: true })
      cy.get('#edit-password-pass2').type(password, { force: true })
      cy.get('#edit-first-name').type('Automated', { force: true })
      cy.get('#edit-last-name').type('Test User', { force: true })
      cy.get('#edit-company-name').type('Renesas', { force: true })
      cy.get('#edit-job-role').select(1, { force: true })
      cy.get('#edit-address-country-code--2').select('DZ', { force: true })
      cy.wait('@loadCountry').its('response.statusCode').should('eq', 200)
      cy.get('.ajax-progress').should('not.exist')
      cy.get('[id^="edit-address-locality"]').type('Test City', { force: true })
      cy.get('[id^="edit-address-postal-code"]').type('10005', { force: true })
      cy.get('#edit-newsletter-subscription-no').check({ force: true })
      cy.get('#edit-agreement').check({ force: true })
  
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages').should('contain', emailAlreadyExistsMessage)
    })
  
    it('(WW2-T922-02) User cannot login with wrong password', { tags: ['sso', 'graylist-blocklist-registration', 'WW2-4304', 'WW2-T922', 'mlit', 'anonymous'] }, () => {
      const { wrongEmailMessage } = testData1[cy.config('language')]
  
      cy.visit('user/sso-login')
  
      cy.get('#edit-username').type(Cypress.env('account').authenticated.username, { force: true })
      cy.get('#edit-password').type('WRONG PASSWORD', { force: true })
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages').contains(wrongEmailMessage)
    })
  
    it('(WW2-T846) User can reset the password using the \'forgot password?\' link', { tags: ['sso', 'graylist-blocklist-registration', 'WW2-6465', 'WW2-T846', 'anonymous', 'destructive'] }, () => {
  
      // Generate new random user email
      cy.getUserEmail().then(($userAccount) => {
  
        // Fill in registration form with user email
        cy.fillRegistrationForm($userAccount).then(($password) => {
  
          const newUserCredentials = {
            username: $userAccount,
            password: $password
          }
  
          // Log in as admin
          // Get the user registration activation link
          cy.login(Cypress.env('account').admin)
          cy.getNewUserActivationLink(newUserCredentials.username).then(($activationLink) => {
  
            // Log out from admin account
            // Access the activation link
            cy.logout()
            cy.visit($activationLink)
  
            // Fill in the login form to activate the new account
            cy.fillInLoginForm(newUserCredentials)
          })
  
          // Logout from the new user
          // Access the login page
          // Click on the 'forgot password?' link
          cy.logout()
          cy.visit('user/sso-login')
          cy.get('#edit-reset-password').should('be.visible').click({ force: true })
  
          // Send password reset email.
          cy.get('#edit-email').type(newUserCredentials.username, { force: true })
          cy.get('#edit-submit').click({ force: true })
  
          // Log out from new user
          // Log in as admin
          cy.login(Cypress.env('account').admin)
  
          // Get the latest email that the user received
          cy.getLastUserEmailInMailSafety(newUserCredentials.username).then(($emailContent) => {
  
            // Get the password reset link from the email body
            const resetPasswordLink = $emailContent.match(/https:\/\/.*\/(gur\/pwdinitinform.do.*[a-zA-Z0-9])/)
  
            // Log out from admin account
            // Access the password reset link
            cy.logout()
            cy.visit(resetPasswordLink[1])
  
            // Reset password
            newUserCredentials.password = cy.randomString()
            cy.get('#edit-new-password-pass1').type(newUserCredentials.password, { force: true })
            cy.get('#edit-new-password-pass2').type(newUserCredentials.password, { force: true })
            cy.get('#edit-submit').click({ force: true })
  
            // Expect to see confirmation message
            cy.get('.messages').should('contain', 'Your password has been successfully reset. Please log in below.')
  
            // Log in using new password
            cy.fillInLoginForm(newUserCredentials)
          })
        })
      })
    })
  
    it('(WW2-8777) User cannot reset password which does not meet the required criteria', { tags: ['sso', 'graylist-blocklist-registration', 'WW2-8777', 'WW2-T738', 'anonymous', 'destructive'] }, () => {
  
      // Generate new random user email
      cy.getUserEmail().then(($userAccount) => {
  
        // Fill in registration form with user email
        cy.fillRegistrationForm($userAccount).then(($password) => {
  
          const newUserCredentials = {
            username: $userAccount,
            password: $password
          }
  
          // Log in as admin
          // Get the user registration activation link
          cy.login(Cypress.env('account').admin)
          cy.getNewUserActivationLink(newUserCredentials.username).then(($activationLink) => {
  
            // Log out from admin account
            // Access the activation link
            cy.logout()
            cy.visit($activationLink)
  
            // Fill in the login form to activate the new account
            cy.fillInLoginForm(newUserCredentials)
          })
  
          // Send password reset email.
          cy.visit('gur/pwdinitinform.do')
          cy.get('#edit-email').type(newUserCredentials.username, { force: true })
          cy.get('#edit-submit').click({ force: true })
  
          // Log out from new user
          // Log in as admin
          cy.login(Cypress.env('account').admin)
  
          // Get the latest email that the user received
          cy.getLastUserEmailInMailSafety(newUserCredentials.username).then(($emailContent) => {
  
            // Get the password reset link from the email body
            const resetPasswordLink = $emailContent.match(/https:\/\/.*\/(gur\/pwdinitinform.do.*[a-zA-Z0-9])/)
  
            // Log out from admin account
            // Access the password reset link
            cy.logout()
            cy.visit(resetPasswordLink[1])
          })
        })
      })
  
      // Setting the typed password and expected error message.
      const passwordsList = {
        1234: 'Password length must be at least 8 characters.',
        12345678: 'Password must contain a lowercase character.',
        a2345678: 'Password must contain an uppercase character.',
      }
  
      // Fill in the password reset form with each password
      // Expect to see error message
      Object.keys(passwordsList).forEach((password) => {
        const message = passwordsList[password]
        cy.get('#edit-new-password-pass1').type(password, { force: true })
        cy.get('#edit-new-password-pass2').type(password, { force: true })
        cy.get('#idt-okta-change-password-form #edit-submit').click({ force: true })
        cy.get('.messages').should('contain', message)
  
        // Somehow after the first error message, the second assertion only
        // gets the next error message after a reload.
        cy.reload()
      })
    })
  })
  
})

