describe('cypress/e2e/renesas.com/sso/sso_4.spec.js', () => {
  
  describe('SSO', { tags: ['sso'] }, () => {
  
    it('(WW2-15730) User should see the acknowledgement page upon first login', { tags: ['sso', 'WW2-15730', 'authenticated', 'destructive'] }, () => {
      const acknowledgementHeading = 'Acknowledgement of Updated Terms of Use and Privacy Policy'
  
      // Log in as admin
      // Access 'Set User Settings' page
      cy.login(Cypress.env('account').admin)
      cy.visit('admin/config/renesas/qa/user-settings')
      cy.waitAdminToolbar()
  
      // Type GDPR user email
      // Check 'Reset GDPR acceptance flag' option
      // Click on update and expect to see success message
      cy.get('#edit-emails').type(Cypress.env('account').gdpr.username, { force: true })
      cy.get('#edit-user-actions-reset-gdpr-agreement').check()
      cy.get('#edit-submit').click({ force: true })
      cy.get('.messages__content').should('contain', 'Updated 1 accounts')
  
      // log out
      // Log in as GDPR user
      cy.logout()
      cy.visit('user/sso-login')
      cy.fillInLoginForm(Cypress.env('account').gdpr, false)
  
      // Expect to see 'Acknowledgement' page
      // Click on decline
      cy.get('h1').should('contain', acknowledgementHeading)
      cy.get('#edit-decline').click({ force: true })
  
      // Confirm decline
      cy.get('h3').should('contain', 'I choose to decline the new terms of service')
      cy.get('.choose-to-decline-message a.confirm').click({ force: true })
  
      // Log in as GDPR user
      cy.visit('user/sso-login')
      cy.fillInLoginForm(Cypress.env('account').gdpr, false)
  
      // Expect to see 'Acknowledgement' page
      // Click on accept
      // Expect user to log in
      cy.get('h1').should('contain', acknowledgementHeading)
      cy.get('#edit-accept').click({ force: true })
      cy.get('#block-kachow-accountlinks .authenticated ul a', { timeout: 120000 }).last().should('have.attr', 'href').and('include', 'user/logout')
  
      // Log out
      // Log in as GDPR user
      // Note: test will fail if log in fails
      cy.logout()
      cy.login(Cypress.env('account').gdpr)
    })
  
    const usersToTest = [
      {
        id: '01',
        label: 'Canada',
        address: {
          street: '3237 Reserve St',
          city: 'Picton',
          province: 'Ontario',
          postalCode: 'K0K 2T0',
          countryCode: 'CA',
        }
      },
      {
        id: '02',
        label: 'United Kingdom',
        address: {
          street: '49 Featherstone Street',
          city: 'London',
          postalCode: 'EC1Y 8SY',
          countryCode: 'GB',
        }
      }
    ]
  
    usersToTest.forEach((user) => {
      it(`(WW2-17748-${user.id}) User can register and update address with space in postal code [${user.label}]`, { tags: ['sso', `WW2-17748-${user.id}`, 'authenticated', 'destructive'] }, () => {
        const modifyOktaUserProfilePage = 'admin/config/renesas/qa/modify-okta-user-profile'
  
        cy.getUserEmail().then((email) => {
          const address = {
            countryCode: user.address.countryCode,
            locality: user.address.city,
            administrativeArea: user.address.province,
            postalCode: user.address.postalCode,
          }
  
          // Register new user
          cy.fillRegistrationForm(email, address).then((password) => {
            const newUser = { username: email, password }
            // Log in as admin
            // Get the user registration activation link
            cy.login(Cypress.env('account').admin)
            cy.getNewUserActivationLink(newUser.username).then(($activationLink) => {
  
              // Log out from admin account
              // Access the activation link
              cy.logout()
              cy.visit($activationLink)
  
              // Fill in the login form to activate the new account
              cy.fillInLoginForm(newUser)
            })
  
            // Log in as admin
            cy.login(Cypress.env('account').admin)
            // Admin removes postal code
            // Access 'Modify Okta User Profile' page
            cy.visit(modifyOktaUserProfilePage)
            cy.get('#edit-email').type(newUser.username, { force: true })
            cy.get('#edit-field').select('zipCode', { force: true })
            cy.get('#edit-value').clear({ force: true }) // Leave blank to remove
            cy.get('#edit-submit').click({ force: true })
            cy.get('.messages__content').should('contain', 'Profile updated successfully')
            // Log out
            cy.logout()
  
            // User logs in again and is prompted to update profile
            cy.visit('user/sso-login')
            cy.fillInLoginForm(newUser, false)
            // Expecting redirect to update profile
            cy.get('#edit-field-address-0-address-postal-code').as('zipCodeField').should('be.empty')
            // Fill out address again
            cy.get('#edit-field-address-0-address-address-line1').as('street').clear()
            cy.get('@street').type(user.address.street)
            cy.get('#edit-field-address-0-address-locality').as('city').clear()
            cy.get('@city').type(user.address.city)
  
            if (user.address.province) {
              cy.get('#edit-field-address-0-address-administrative-area').select(user.address.province)
            }
            // Enter postal code
            cy.get('@zipCodeField').type(user.address.postalCode)
            // Enter country
            cy.get('select[name="field_address[0][address][country_code]"]').select(user.label)
  
            // Submit form
            cy.get('#edit-submit').click({ force: true })
  
            // Expect user to be logged in successfully
            cy.get('[data-selector="secondary-menus"] .authenticated').within(() => {
              cy.get('[href="#accountMenu"].r').should('be.visible')
            })
          })
        })
      })
    })
  })
  
})

describe('cypress/e2e/renesas.com/sso/user-registration_1.spec.js', () => {
  
  describe('SSO - User Registration', { tags: ['sso', 'user-registration'] }, () => {
  
    it('(WW2-8807-01) Non-renesas user cannot register a new account if registration uses a blacklisted country', { tags: ['graylist-blocklist-registration', 'user-registration', 'sso', 'WW2-8807-01', 'anonymous', 'smoke-test', 'destructive'] }, () => {
  
      // Blacklisted address (North Korea)
      const address = {
        countryCode: 'KP',
        administrativeArea: '01'
      }
  
      // Generate new random user email
      cy.getUserEmail().then(($userAccount) => {
  
        // Fill in registration form with user email
        cy.fillRegistrationForm($userAccount, address).then(($password) => {
          const newUserCredentials = {
            username: $userAccount,
            password: $password
          }
  
          // Log in as admin
          // Get the user registration activation link
          cy.login(Cypress.env('account').admin)
          cy.getNewUserActivationLink(newUserCredentials.username).then(($activationLink) => {
  
            // Log out from admin account
            // Access the activation link
            cy.logout()
            cy.visit($activationLink)
  
            // Fill in the login form to activate the new account
            // pass 'false' to expect login to fail
            cy.fillInLoginForm(newUserCredentials, false)
          })
        })
      })
  
      // Expect to see 'registration denied' messages
      cy.get('.registration .page-title').first().should('contain', 'You registration has been denied')
      cy.get('.registration .notification').first().should('contain', 'Due to your geographic location, your account has been blocked.')
    })
  
    it('(WW2-8807-02) Non-renesas user cannot register a new account if registration uses a graylisted country', { tags: ['graylist-blocklist-registration', 'user-registration', 'sso', 'WW2-8807-02', 'anonymous', 'smoke-test', 'destructive'] }, () => {
  
      // Graylisted address (Ukraine)
      const address = {
        countryCode: 'UA',
        administrativeArea: '30'
      }
  
      // Generate new random user email
      cy.getUserEmail().then(($userAccount) => {
  
        // Fill in registration form with user email
        cy.fillRegistrationForm($userAccount, address).then(($password) => {
          const newUserCredentials = {
            username: $userAccount,
            password: $password
          }
  
          // Log in as admin
          // Get the user registration activation link
          cy.login(Cypress.env('account').admin)
          cy.getNewUserActivationLink(newUserCredentials.username).then(($activationLink) => {
  
            // Log out from admin account
            // Access the activation link
            cy.logout()
            cy.visit($activationLink)
  
            // Fill in the login form to activate the new account
            // pass 'false' to expect login to fail
            cy.fillInLoginForm(newUserCredentials, false)
          })
        })
      })
  
      // Expect to see registration denied messages
      cy.get('.registration .page-title').first().should('contain', 'Thank you. Your registration is under review.')
      cy.get('.registration .notification').first().should('contain', 'Due to your geographic location, your account registration is under review by our trade compliance team.')
    })
  })
  
})

describe('cypress/e2e/renesas.com/sso/user-registration_2.spec.js', () => {
  
  describe('SSO - User Registration', { tags: ['sso', 'user-registration'] }, () => {
  
    const testData = {
      en: {
        selectYourCountryRegionText: 'Select Your Country/Region',
        selectText: 'Select',
        passwordRequirements: {
          title: 'Password Requirements',
          minChars: 'Password must be at least 8 characters',
          lowercase: 'Include a lowercase letter',
          uppercase: 'Include an uppercase letter',
          number: 'Include a number',
          noEmail: 'Does not contain part of your email address'
        }
      },
      ja: {
        selectYourCountryRegionText: '国/地域を選択してください',
        selectText: '選択',
        passwordRequirements: {
          title: 'パスワード要件',
          minChars: 'パスワードは8文字以上必要です',
          lowercase: '小文字を含めてください',
          uppercase: '大文字を含めてください',
          number: '数字を含めてください',
          noEmail: 'Eメールアドレスの一部が含まれておりません'
        }
      },
      zh: {
        selectYourCountryRegionText: '选择您的国家/地区',
        selectText: '选择',
        passwordRequirements: {
          title: '密码要求',
          minChars: '密码至少包含 8 个字符',
          lowercase: '包含一个小写字母',
          uppercase: '包含一个大写字母',
          number: '包含一个数字',
          noEmail: '不包含您电子邮件地址的部分内容'
        }
      }
    }
  
    beforeEach(() => {
      if (Cypress.env('dryRun') === true) {
        return
      }
      // CDN thinks this comes from a bot
      // so we need to add a secret header
      // to get around it on production
      cy.onProdEnv().then(($onProd) => {
        if ($onProd) {
          cy.intercept('POST', '**/gur/ssoRegisterUser.do**', (req) => {
            req.headers['X-REL-Bypass'] = Cypress.env('prodBotHeader')
          })
        }
      })
    })
  
    it('(WW2-15413-01) User should see correct language on register page based on site language', { tags: ['sso', 'user-registration', 'WW2-15413-01', 'mlit', 'anonymous'] }, () => {
  
      // Map of language codes to display text
      const language = cy.config('language')
      const languageDisplayText = {
        en: 'English',
        ja: '日本語',
        zh: '简体中文'
      }
  
      // Visit register page
      cy.visit('register')
  
      // Expect language dropdown has the correct default option selected
      cy.get('#edit-language').should('have.value', (language === 'zh' ? 'zh-hans' : language))
      cy.get('#edit-language option:selected').should('have.text', languageDisplayText[language])
    })
  
    it('(WW2-15413-02) User should see \'Select\' option selected as default on \'Job Role\' field', { tags: ['sso', 'user-registration', 'WW2-15413-02', 'mlit', 'anonymous'] }, () => {
  
      const { selectText } = testData[cy.config('language')]
  
      // Visit register page
      cy.visit('register')
  
      /**
       * Expect:
       *  - job role field to be visible
       *  - 'Select' option to be selected by default
       */
      cy.get('#edit-job-role').should('be.visible').scrollIntoView()
      cy.get('#edit-job-role option:selected').should('have.value', '').and('contain', selectText)
    })
  
    it('(WW2-15413-03) User should see \'Select\' option selected as default on \'Prefecture\' field', { tags: ['sso', 'WW2-15413-03', 'mlit', 'anonymous'] }, () => {
  
      const { selectText } = testData[cy.config('language')]
  
      // Access register page
      cy.visit('register')
      cy.get('[id^="edit-address-administrative-area"]').as('addressAdministrativeArea').scrollIntoView()
  
      /**
       * Expect:
       *  - prefecture field to be visible
       *  - 'Select' option to be selected by default
       */
      cy.get('@addressAdministrativeArea').should('exist').within(() => {
        cy.get('option:selected').should('have.value', '').and('contain', selectText)
      })
    })
  
    it('(WW2-15413-04) User should see \'Select Your Country/Region\' option selected as default on \'Country/Region\' field', { tags: ['sso', 'user-registration', 'WW2-15413-04', 'mlit', 'anonymous'] }, () => {
  
      const { selectYourCountryRegionText } = testData[cy.config('language')]
  
      // Access register page
      cy.visit('register')
  
      // Expect 'country/region' field to exist
      cy.get('select.country').should('exist').within(() => {
        cy.get('option:selected').should('have.text', selectYourCountryRegionText)
      })
    })
  
    it('(WW2-15413-05) User should see password requirements on register page', { tags: ['sso', 'user-registration', 'WW2-15413-05', 'mlit', 'anonymous'] }, () => {
  
      const { passwordRequirements } = testData[cy.config('language')]
  
      // Access register page
      cy.visit('register')
  
      // Expect to see password requirements
      cy.get('#edit-password').within(() => {
        cy.get('strong').should('have.text', passwordRequirements.title).and('be.visible')
        cy.get('li').should('contain', passwordRequirements.minChars)
          .and('contain', passwordRequirements.lowercase)
          .and('contain', passwordRequirements.uppercase)
          .and('contain', passwordRequirements.number)
          .and('contain', passwordRequirements.noEmail)
          .and('be.visible')
      })
    })
  })
  
})

describe('cypress/e2e/renesas.com/sso/user-registration_3.spec.js', () => {
  
  describe('SSO - User Registration', { tags: ['sso', 'user-registration'] }, () => {
  
    const testData1 = ['US', 'AU', 'CN', 'IN', 'KR']
  
    testData1.forEach((country, index) => {
      it(`(WW2-15413-06-0${index + 1}) User from ${country} should see updated fields based on the country`, { tags: ['sso', 'user-registration', 'WW2-15413-06', 'anonymous'] }, () => {
  
        const cityLabel = 'City'
        const suburbLabel = 'Suburb'
  
        const stateLabel = 'State'
        const provinceLabel = 'Province'
        const doSiLabel = 'Do/Si'
  
        const zipCodeLabel = 'Zip code'
        const postalCodeLabel = 'Postal code'
        const pinCodeLabel = 'Pin code'
  
        // Create alias to wait for page elements
        cy.intercept('GET', '**/ajax/user/data-settings?**').as('passwordStrength')
        cy.intercept('POST', '**/gur/ssoRegisterUser.do?client_id=**&ajax_form=1&_wrapper_format=drupal_ajax**').as('loadCountry')
  
        // Access register page
        cy.visit('register')
  
        // Wait for password field to load
        cy.wait('@passwordStrength').its('response.statusCode').should('eq', 200)
  
        // Select Country
        // Wait for country field to load after selecting option
        cy.get('#edit-address-country-code--2').select(country, { force: true })
        cy.wait('@loadCountry').its('response.statusCode').should('eq', 200)
  
        switch (country) {
  
        case 'US':
          /**
           * Expect 'United States' option to show:
           *  - City
           *  - State
           *  - Zip code
           */
          cy.get('[id^="edit-address-locality"]').as('cityField').should('exist').and('be.visible')
          cy.get('@cityField').siblings('label').should('contain', cityLabel)
          cy.get('[id^="edit-address-administrative-area"]').as('stateField').should('exist').and('be.visible')
          cy.get('@stateField').siblings('label').should('contain', stateLabel)
          cy.get('[id^="edit-address-postal-code"]').as('zipCodeField').should('exist').and('be.visible')
          cy.get('@zipCodeField').siblings('label').should('contain', zipCodeLabel)
          break
  
        case 'AU':
          /**
           * Expect 'Australia' option to show:
           *  - Suburb
           *  - State
           *  - Postal code
           */
          cy.get('[id^="edit-address-locality"]').as('suburbField').should('exist').and('be.visible')
          cy.get('@suburbField').siblings('label').should('contain', suburbLabel)
          cy.get('[id^="edit-address-administrative-area"]').as('stateField').should('exist').and('be.visible')
          cy.get('@stateField').siblings('label').should('contain', stateLabel)
          cy.get('[id^="edit-address-postal-code"]').as('postalCodeField').should('exist').and('be.visible')
          cy.get('@postalCodeField').siblings('label').should('contain', postalCodeLabel)
          break
  
        case 'CN':
          /**
           * Expect 'China' option to show:
           *  - City
           *  - State
           *  - Postal code
           */
          cy.get('[id^="edit-address-locality"]').as('cityField').should('exist').and('be.visible')
          cy.get('@cityField').siblings('label').should('contain', cityLabel)
          cy.get('[id^="edit-address-administrative-area"]').as('provinceLabel').should('exist').and('be.visible')
          cy.get('@provinceLabel').siblings('label').should('contain', provinceLabel)
          cy.get('[id^="edit-address-postal-code"]').as('postalCodeField').should('exist').and('be.visible')
          cy.get('@postalCodeField').siblings('label').should('contain', postalCodeLabel)
          break
  
        case 'IN':
          /**
           * Expect 'India' option to show:
           *  - City
           *  - State
           *  - Pin code
           */
          cy.get('[id^="edit-address-locality"]').as('cityField').should('exist').and('be.visible')
          cy.get('@cityField').siblings('label').should('contain', cityLabel)
          cy.get('[id^="edit-address-administrative-area"]').as('stateField').should('exist').and('be.visible')
          cy.get('@stateField').siblings('label').should('contain', stateLabel)
          cy.get('[id^="edit-address-postal-code"]').as('pinCodeField').should('exist').and('be.visible')
          cy.get('@pinCodeField').siblings('label').should('contain', pinCodeLabel)
          break
  
        case 'KR':
          /**
           * Expect 'South Korea' option to show:
           *  - City
           *  - State
           *  - Postal code
           */
          cy.get('[id^="edit-address-locality"]').as('cityField').should('exist').and('be.visible')
          cy.get('@cityField').siblings('label').should('contain', cityLabel)
          cy.get('[id^="edit-address-administrative-area"]').as('doSiField').should('exist').and('be.visible')
          cy.get('@doSiField').siblings('label').should('contain', doSiLabel)
          cy.get('[id^="edit-address-postal-code"]').as('postalCodeField').should('exist').and('be.visible')
          cy.get('@postalCodeField').siblings('label').should('contain', postalCodeLabel)
          break
  
        default:
          break
        }
      })
    })
  })
  
})

