      // Change overview to 'restrict html' and fill in 'description' field
      cy.get('#edit-body-0-format--2').select('restricted_html', { force: true })
      cy.get('#edit-body-0-value').as('descriptionField').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('@descriptionField').type(productCategoryTitle, { force: true })
  
      // Expect to see “New Layout” checkbox
