      cy.get('[data-drupal-selector="edit-field-story-telling-tabs-0-subform-field-body-0-value"]').as('descriptionTexarea').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('@descriptionTexarea').type(storyTellingBody1, { force: true })
      cy.wait(5000)
  
      // Click the Add Story-telling Add More button
      cy.get('[data-drupal-selector="edit-field-story-telling-tabs-add-more"]')
        .find('input[type="submit"]')
        .click()
  
      // Add Story Telling Tab Title2
      cy.get('[data-drupal-selector="edit-field-story-telling-tabs-1-subform-field-title-0-value"]').type(storyTellingTitle2, { force: true })
  
      // Add Story Telling Description2
      cy.get('select[id^="edit-field-story-telling-tabs-1-subform-field-body-0-format"]').select('restricted_html')
      cy.get('[data-drupal-selector="edit-field-story-telling-tabs-1-subform-field-body-0-value"]').as('descriptionTexarea').should('have.attr', 'style').and('not.include', 'visibility: hidden; display: none;')
      cy.get('@descriptionTexarea').type(storyTellingBody2, { force: true })
